window.FLASHDECK = {"slug":"bouw_en_bewegen","subject":"Bouw en Bewegen","source":"Itemlijst anatomie Bouw en Bewegen (Canvas)","total":293,"regions":[{"name":"Bovenste extremiteit","groups":[{"name":"Skelet","cards":[{"id":"bovenste_ext_clavicula","f":"clavicula","b":["Sleutelbeen: S-vormig bot tussen sternum (SC-gewricht) en acromion (AC-gewricht).","Volledig subcutaan palpabel.","Klinisch: meest gebroken bot bij val op de schouder, meestal in het middelste derde."],"n":6},{"id":"bovenste_ext_scapula","f":"scapula","b":["Schouderblad: plat driehoekig bot op de dorsale thoraxwand (ter hoogte van rib 2–7).","Onderdelen: spina scapulae, acromion, processus coracoideus, cavitas glenoidalis, fossa supra- en infraspinata.","Beweegt mee via het scapulothoracale glijvlak (geen echt gewricht)."],"n":4},{"id":"bovenste_ext_acromion","f":"acromion","b":["Laterale voortzetting van de spina scapulae; vormt het schouderdak.","Articuleert met de clavicula (AC-gewricht).","Palpabel als het hoogste punt van de schouder; onder het acromion liggen de bursa subacromialis en de m. supraspinatuspees."],"n":4},{"id":"bovenste_ext_processus_coracoideus","f":"processus coracoideus","b":["Ravenbekuitsteeksel: haakvormig uitsteeksel aan de voorzijde van de scapula.","Aanhechting: m. pectoralis minor, m. coracobrachialis, caput breve m. biceps brachii.","Lig. coracoclaviculare verbindt hem met de clavicula; palpabel onder het laterale derde van de clavicula."],"n":4},{"id":"bovenste_ext_spina_scapulae","f":"spina scapulae","b":["Benige kam op de achterzijde van de scapula; scheidt fossa supraspinata en fossa infraspinata.","Loopt lateraal over in het acromion.","Aanhechting m. trapezius (bovenrand) en origo m. deltoideus (pars spinalis). Goed palpabel."],"n":0},{"id":"bovenste_ext_cavitas_glenoidalis","f":"cavitas glenoidalis","b":["Ondiepe gewrichtskom van de scapula voor de humeruskop.","Wordt verdiept door het labrum glenoidale.","Klein t.o.v. de humeruskop → veel beweeglijkheid, weinig benige stabiliteit (luxatiegevoelig)."],"n":4},{"id":"bovenste_ext_humerus","f":"humerus","b":["Opperarmbeen: pijpbeen tussen schouder- en ellebooggewricht.","Proximaal: caput, collum anatomicum/chirurgicum, tubercula. Distaal: trochlea, capitulum, epicondylen.","Schachtfractuur bedreigt de n. radialis (sulcus nervi radialis)."],"n":14},{"id":"bovenste_ext_caput_humeri","f":"caput humeri","b":["Bolvormige gewrichtskop van de humerus, articuleert met de cavitas glenoidalis.","Wijst mediaal, craniaal en dorsaal (retroversie).","Gaat over in het collum anatomicum."],"n":1},{"id":"bovenste_ext_collum_chirurgicum_en_anatomicum","f":"collum chirurgicum en anatomicum","b":["Collum anatomicum: insnoering direct onder het kraakbeen van de caput humeri (aanhechting kapsel).","Collum chirurgicum: smaller deel onder de tubercula; veel voorkomende fractuurplaats bij ouderen.","Fractuur collum chirurgicum bedreigt de n. axillaris en a. circumflexa humeri posterior."],"n":1},{"id":"bovenste_ext_tuberculum_majus_en_minus","f":"tuberculum majus en minus","b":["Tuberculum majus (lateraal): aanhechting m. supraspinatus, m. infraspinatus, m. teres minor.","Tuberculum minus (ventraal): aanhechting m. subscapularis.","Daartussen ligt de sulcus intertubercularis."],"n":2},{"id":"bovenste_ext_sulcus_intertubercularis","f":"sulcus intertubercularis","b":["Groeve tussen tuberculum majus en minus aan de voorzijde van de humerus.","Bevat de pees van het caput longum m. biceps brachii.","Op de randen hechten m. pectoralis major (lateraal), m. latissimus dorsi en m. teres major (mediaal) aan."],"n":0},{"id":"bovenste_ext_epicondylus_medialis_en_lateralis_humerus","f":"epicondylus medialis en lateralis (humerus)","b":["Benige uitsteeksels aan weerszijden van het distale humeruseinde, goed palpabel.","Medialis: origo van de onderarmflexoren (caput commune flexorum); n. ulnaris loopt erachter langs (‘telefoonbotje’).","Lateralis: origo van de onderarmextensoren (caput commune extensorum). Overbelasting → tenniselleboog."],"n":3},{"id":"bovenste_ext_condylus_humeri_trochlea_en_capitulum","f":"condylus humeri: trochlea en capitulum","b":["Trochlea: katrolvormig gewrichtsvlak mediaal, articuleert met de incisura trochlearis van de ulna (scharnier).","Capitulum: bolvormig gewrichtsvlak lateraal, articuleert met de caput radii.","Samen het distale gewrichtsvlak van de humerus."],"n":0},{"id":"bovenste_ext_radius","f":"radius","b":["Spaakbeen: laterale (duimzijde) onderarmbot.","Proximaal smal (caput radii), distaal breed (draagt het polsgewricht).","Draait bij pronatie/supinatie om de ulna. Distale radiusfractuur (Colles) is de meest voorkomende fractuur na val op gestrekte hand."],"n":6},{"id":"bovenste_ext_caput_radii","f":"caput radii","b":["Schijfvormige kop van de radius.","Articuleert met het capitulum humeri en de incisura radialis ulnae.","Wordt omsloten door het lig. anulare radii; draait bij pro- en supinatie. Palpabel distaal van de epicondylus lateralis."],"n":0},{"id":"bovenste_ext_tuberositas_radii","f":"tuberositas radii","b":["Ruw uitsteeksel mediaal-ventraal net onder de caput radii.","Aanhechting van de bicepspees (m. biceps brachii).","Daardoor is de biceps ook een krachtige supinator."],"n":0},{"id":"bovenste_ext_processus_styloideus_radii","f":"processus styloideus radii","b":["Distaal, lateraal uitsteeksel van de radius.","Ligt ca. 1 cm distaler dan de processus styloideus ulnae.","Palpabel in de anatomische snuifdoos-regio; aanhechting m. brachioradialis."],"n":1},{"id":"bovenste_ext_ulna","f":"ulna","b":["Ellepijp: mediale (pinkzijde) onderarmbot.","Proximaal breed (olecranon, incisura trochlearis), distaal smal (caput ulnae).","Vormt het scharnier met de trochlea humeri."],"n":6},{"id":"bovenste_ext_olecranon","f":"olecranon","b":["Proximaal uitsteeksel van de ulna: de ‘elleboogpunt’.","Aanhechting van de m. triceps brachii.","Bursa olecrani ligt erover; subcutaan palpabel."],"n":3},{"id":"bovenste_ext_processus_styloideus_ulnae","f":"processus styloideus ulnae","b":["Klein distaal uitsteeksel aan de dorsomediale kant van de ulna.","Palpabel aan de pinkzijde van de pols.","Aanhechtingsplaats van de discus articularis (TFCC) van het distale radio-ulnaire gewricht."],"n":0},{"id":"bovenste_ext_ossa_carpalia","f":"ossa carpalia","b":["8 handwortelbeentjes in twee rijen.","Proximaal (radiaal→ulnair): scaphoideum, lunatum, triquetrum, pisiforme.","Distaal: trapezium, trapezoideum, capitatum, hamatum. Ezelsbrug: ‘Scheepje Lunatum Triquetrum Pisiforme, Trapezium Trapezoideum Capitatum Hamatum’."],"n":0},{"id":"bovenste_ext_os_scaphoideum","f":"os scaphoideum","b":["Grootste bot van de proximale carpale rij, aan de duimzijde.","Palpabel in de anatomische snuifdoos.","Meest gebroken handwortelbeentje (val op gestrekte hand); bloedvoorziening van distaal → risico op avasculaire necrose en pseudoartrose van het proximale deel."],"n":5},{"id":"bovenste_ext_os_lunatum","f":"os lunatum","b":["Halvemaanvormig bot in het midden van de proximale carpale rij.","Articuleert met de radius.","Klinisch: meest geluxeerde handwortelbeentje; kan de n. medianus in de carpale tunnel comprimeren. Avasculaire necrose = ziekte van Kienböck."],"n":4},{"id":"bovenste_ext_os_pisiforme","f":"os pisiforme","b":["Erwtvormig sesambeen ventraal op het os triquetrum (pinkzijde).","Ligt in de pees van de m. flexor carpi ulnaris.","Palpabel aan de ulnaire palmaire zijde van de pols; vormt mee de wand van het kanaal van Guyon."],"n":3},{"id":"bovenste_ext_os_triquetrum_trapezium_trapezoideum_capitatum_","f":"os triquetrum, trapezium, trapezoideum, capitatum, hamatum","b":["Triquetrum: proximale rij, ulnair, draagt het pisiforme.","Trapezium: distale rij aan de duimzijde, zadelgewricht met metacarpale I (CMC-I).","Trapezoideum: naast trapezium. Capitatum: grootste carpale bot, centraal. Hamatum: met haakje (hamulus) aan de ulnaire zijde, begrenst canalis ulnaris en carpale tunnel."],"n":3},{"id":"bovenste_ext_ossa_metacarpalia_i_v","f":"ossa metacarpalia (I–V)","b":["Middenhandsbeentjes, genummerd van duim (I) tot pink (V).","Proximaal (basis) articuleren met de distale carpale rij (CMC), distaal (caput) met de phalanges (MCP).","Fractuur van het caput MC V = ‘boxer’s fracture’."],"n":0},{"id":"bovenste_ext_digiti_i_pollex_v_digitus_minimus_phalanges","f":"digiti I (pollex) – V (digitus minimus): phalanges","b":["Duim (pollex) heeft 2 phalanges: proximalis en distalis.","Digiti II–V hebben elk 3 phalanges: proximalis, media en distalis.","Gewrichten: MCP, PIP en DIP (duim: MCP en IP)."],"n":0}]},{"name":"Gewrichten","cards":[{"id":"bovenste_ext_articulatio_sternoclavicularis_sc_gewricht","f":"articulatio sternoclavicularis (SC-gewricht)","b":["Tussen mediale uiteinde clavicula, manubrium sterni en 1e rib.","Zadelgewricht met discus articularis → functioneel kogelgewricht.","Enige benige verbinding van de arm met de romp."],"n":1},{"id":"bovenste_ext_articulatio_acromioclavicularis_ac_gewricht","f":"articulatio acromioclavicularis (AC-gewricht)","b":["Tussen laterale uiteinde clavicula en acromion.","Vlak (glij)gewricht.","Verstevigd door lig. acromioclaviculare en lig. coracoclaviculare. AC-luxatie bij val op de schouder (‘pianotoetsfenomeen’)."],"n":4},{"id":"bovenste_ext_lig_coracoclaviculare_lig_conoideum_en_trapezoi","f":"ligamentum coracoclaviculare (lig. conoideum en trapezoideum)","b":["Sterke band tussen processus coracoideus en onderzijde clavicula.","Twee delen: lig. conoideum (mediaal) en lig. trapezoideum (lateraal).","Belangrijkste stabilisator van het AC-gewricht (voorkomt dat de scapula naar caudaal zakt)."],"n":2},{"id":"bovenste_ext_lig_acromioclaviculare","f":"ligamentum acromioclaviculare","b":["Band over de bovenzijde van het AC-gewricht, tussen acromion en clavicula.","Versterkt het gewrichtskapsel; zorgt voor horizontale stabiliteit.","Scheurt als eerste bij een AC-letsel."],"n":2},{"id":"bovenste_ext_articulatio_glenohumeralis_schoudergewricht","f":"articulatio glenohumeralis (schoudergewricht)","b":["Kogelgewricht tussen caput humeri en cavitas glenoidalis.","Bewegingen: ante-/retroflexie, ab-/adductie, endo-/exorotatie, circumductie.","Meest beweeglijke gewricht van het lichaam; stabiliteit vooral door spieren (rotatorenmanchet) → luxeert vaak naar ventraal-caudaal."],"n":14},{"id":"bovenste_ext_labrum_glenoidale","f":"labrum glenoidale","b":["Fibrocartilagineuze ring rond de rand van de cavitas glenoidalis.","Vergroot en verdiept de kom → meer stabiliteit.","Origo van de pees van het caput longum m. biceps brachii (bovenrand). Letsel bij luxatie: Bankart-laesie."],"n":1},{"id":"bovenste_ext_rotatorenmanchet_rotator_cuff","f":"rotatorenmanchet (rotator cuff)","b":["4 spieren die de humeruskop in de kom centreren: m. supraspinatus, m. infraspinatus, m. teres minor, m. subscapularis (SITS).","Pezen versmelten met het gewrichtskapsel.","Klinisch: supraspinatuspees raakt het vaakst beschadigd (impingement, ruptuur)."],"n":0},{"id":"bovenste_ext_bursa_subacromialis_subdeltoidea","f":"bursa subacromialis (subdeltoidea)","b":["Slijmbeurs tussen acromion/m. deltoideus en de pees van de m. supraspinatus.","Laat de pees soepel onder het schouderdak glijden bij abductie.","Ontsteking (bursitis) geeft pijn bij abductie (painful arc 60–120°)."],"n":2},{"id":"bovenste_ext_articulatio_cubiti_ellebooggewricht","f":"articulatio cubiti (ellebooggewricht)","b":["Samengesteld gewricht met één kapsel: humero-ulnair, humeroradiaal en proximaal radio-ulnair.","Bewegingen: flexie/extensie (scharnier) en pro-/supinatie (rad).","Collaterale banden mediaal (ulnair) en lateraal (radiaal) + lig. anulare radii."],"n":8},{"id":"bovenste_ext_articulatio_humero_ulnaris_humeroradialis_en_ra","f":"articulatio humero-ulnaris, humeroradialis en radio-ulnaris proximalis","b":["Humero-ulnaris: trochlea humeri – incisura trochlearis ulnae; scharniergewricht (flexie/extensie).","Humeroradialis: capitulum – caput radii; kogelgewricht (functioneel beperkt).","Radio-ulnaris proximalis: caput radii – incisura radialis ulnae; radgewricht (pro-/supinatie)."],"n":2},{"id":"bovenste_ext_lig_anulare_radii","f":"ligamentum anulare radii","b":["Ringvormige band om de caput radii, aan de ulna vastgehecht.","Houdt de radiuskop tegen de ulna tijdens draaien.","Klinisch: bij jonge kinderen kan de radiuskop eruit schieten bij trekken aan de arm (‘zandloperelleboog’/pronatio dolorosa)."],"n":0},{"id":"bovenste_ext_bursa_olecrani","f":"bursa olecrani","b":["Subcutane slijmbeurs over het olecranon.","Vermindert wrijving tussen huid en bot.","Bursitis olecrani (‘studentenelleboog’) door druk of trauma; zichtbare zwelling."],"n":0},{"id":"bovenste_ext_articulatio_radio_ulnaris_distalis","f":"articulatio radio-ulnaris distalis","b":["Tussen caput ulnae en incisura ulnaris radii.","Radgewricht: radius draait om de ulna bij pro- en supinatie.","Gestabiliseerd door de discus articularis (TFCC)."],"n":2},{"id":"bovenste_ext_membrana_interossea_antebrachii","f":"membrana interossea antebrachii","b":["Stevige bindweefselplaat tussen de schachten van radius en ulna.","Verbindt de botten, verdeelt krachten van radius naar ulna.","Scheidt het ventrale (flexoren) en dorsale (extensoren) compartiment; origo van diepe onderarmspieren."],"n":1},{"id":"bovenste_ext_articulatio_radiocarpalis_polsgewricht","f":"articulatio radiocarpalis (polsgewricht)","b":["Tussen distale radius (+ discus articularis) en de proximale carpale rij (scaphoideum, lunatum, triquetrum).","Ellipsoïd (eivormig) gewricht: palmairflexie/dorsaalflexie en radiaal-/ulnairdeviatie.","Ulna neemt niet direct deel (discus ertussen)."],"n":8},{"id":"bovenste_ext_mediocarpale_en_intercarpale_gewrichten","f":"mediocarpale en intercarpale gewrichten","b":["Mediocarpaal: tussen proximale en distale carpale rij; draagt bij aan flexie/extensie van de pols.","Intercarpaal: tussen de carpalia binnen een rij; vlakke glijgewrichten.","Samen met het radiocarpale gewricht verzorgen ze de beweging van de pols."],"n":0},{"id":"bovenste_ext_articulatio_carpometacarpalis_pollicis_cmc_i","f":"articulatio carpometacarpalis pollicis (CMC-I)","b":["Tussen os trapezium en basis metacarpale I.","Zadelgewricht: flexie/extensie, abductie/adductie en oppositie van de duim.","Klinisch: veel voorkomende plek van artrose (rizartrose)."],"n":0},{"id":"bovenste_ext_articulationes_carpometacarpales_ii_v_cmc_ii_v","f":"articulationes carpometacarpales II–V (CMC II–V)","b":["Tussen distale carpale rij en basis MC II–V.","Vlakke gewrichten; II–III bijna onbeweeglijk, IV–V iets beweeglijker (kommen van de hand).","Vormen het stabiele centrum van de hand."],"n":0},{"id":"bovenste_ext_articulationes_metacarpophalangeae_mcp_i_v","f":"articulationes metacarpophalangeae (MCP I–V)","b":["Tussen caput metacarpale en basis phalanx proximalis.","Ellipsoïd (condylair) gewricht: flexie/extensie en ab-/adductie (vingers spreiden).","Knokkels van de vuist."],"n":0},{"id":"bovenste_ext_articulationes_interphalangeae_proximalis_en_di","f":"articulationes interphalangeae proximalis en distalis (PIP en DIP)","b":["PIP: tussen phalanx proximalis en media. DIP: tussen phalanx media en distalis.","Scharniergewrichten: alleen flexie en extensie.","Duim heeft één IP-gewricht."],"n":1}]},{"name":"Spieren","cards":[{"id":"bovenste_ext_m_trapezius","f":"m. trapezius","b":["Functie: elevatie (pars descendens), retractie (pars transversa), depressie (pars ascendens) en laterorotatie van de scapula.","Innervatie: n. accessorius (N. XI).","Origo: os occipitale, lig. nuchae, processus spinosi C7–T12. Insertie: laterale clavicula, acromion, spina scapulae.","Extrinsieke (oppervlakkige) rugspier."],"n":6},{"id":"bovenste_ext_m_latissimus_dorsi","f":"m. latissimus dorsi","b":["Functie: extensie, adductie en endorotatie van de schouder (‘zwemmersspier’).","Innervatie: n. thoracodorsalis.","Origo: processus spinosi T7–L5, fascia thoracolumbalis, crista iliaca. Insertie: bodem sulcus intertubercularis humeri.","Extrinsieke rugspier."],"n":6},{"id":"bovenste_ext_m_rhomboideus_major_en_minor","f":"m. rhomboideus major en minor","b":["Functie: retractie (adductie) en mediorotatie van de scapula; fixeren scapula tegen de thorax.","Innervatie: n. dorsalis scapulae.","Origo: processus spinosi C7–T5. Insertie: margo medialis scapulae.","Liggen onder de m. trapezius."],"n":6},{"id":"bovenste_ext_m_levator_scapulae","f":"m. levator scapulae","b":["Functie: elevatie en mediorotatie van de scapula.","Innervatie: n. dorsalis scapulae (+ C3–C4).","Origo: processus transversi C1–C4. Insertie: angulus superior scapulae."],"n":7},{"id":"bovenste_ext_m_pectoralis_major","f":"m. pectoralis major","b":["Functie: anteflexie, endorotatie en adductie van de schouder.","Innervatie: n. pectoralis medialis en lateralis.","Origo: clavicula, sternum, ribkraakbeen 1–6. Insertie: crista tuberculi majoris (laterale lip sulcus intertubercularis)."],"n":1},{"id":"bovenste_ext_m_pectoralis_minor","f":"m. pectoralis minor","b":["Functie: protractie en depressie van de scapula; hulpademhalingsspier.","Innervatie: n. pectoralis medialis.","Origo: rib 3–5. Insertie: processus coracoideus."],"n":0},{"id":"bovenste_ext_m_serratus_anterior","f":"m. serratus anterior","b":["Functie: protractie en laterorotatie van de scapula (nodig voor abductie > 90°); drukt scapula tegen de thorax.","Innervatie: n. thoracicus longus.","Origo: rib 1–8/9 (lateraal). Insertie: margo medialis scapulae (ventraal).","Uitval → scapula alata."],"n":1},{"id":"bovenste_ext_m_deltoideus","f":"m. deltoideus","b":["Functie: abductie van de schouder (pars acromialis); ook anteflexie/endorotatie (pars clavicularis) en retroflexie/exorotatie (pars spinalis).","Innervatie: n. axillaris.","Origo: laterale clavicula, acromion, spina scapulae. Insertie: tuberositas deltoidea humeri."],"n":7},{"id":"bovenste_ext_m_teres_major","f":"m. teres major","b":["Functie: adductie, endorotatie en extensie van de schouder.","Innervatie: n. subscapularis (inferior).","Origo: angulus inferior scapulae. Insertie: crista tuberculi minoris (mediale lip sulcus intertubercularis).","Geen rotatorcuffspier!"],"n":7},{"id":"bovenste_ext_m_supraspinatus","f":"m. supraspinatus","b":["Functie: initiator van abductie van de schouder (eerste ~15°); rotatorcuffspier.","Innervatie: n. suprascapularis.","Origo: fossa supraspinata. Insertie: tuberculum majus (bovenste facet).","Pees loopt onder het acromion → vaakst betrokken bij impingement/ruptuur."],"n":2},{"id":"bovenste_ext_m_infraspinatus","f":"m. infraspinatus","b":["Functie: exorotatie van de schouder; rotatorcuffspier.","Innervatie: n. suprascapularis.","Origo: fossa infraspinata. Insertie: tuberculum majus (middelste facet)."],"n":2},{"id":"bovenste_ext_m_teres_minor","f":"m. teres minor","b":["Functie: exorotatie (en lichte adductie) van de schouder; rotatorcuffspier.","Innervatie: n. axillaris.","Origo: margo lateralis scapulae. Insertie: tuberculum majus (onderste facet)."],"n":3},{"id":"bovenste_ext_m_subscapularis","f":"m. subscapularis","b":["Functie: endorotatie van de schouder; rotatorcuffspier.","Innervatie: n. subscapularis (superior en inferior).","Origo: fossa subscapularis (voorzijde scapula). Insertie: tuberculum minus.","Enige rotatorcuffspier aan de voorkant."],"n":1},{"id":"bovenste_ext_m_coracobrachialis","f":"m. coracobrachialis","b":["Functie: anteflexie en adductie van de schouder.","Innervatie: n. musculocutaneus (doorboort de spier).","Origo: processus coracoideus. Insertie: mediaal midden humerusschacht."],"n":1},{"id":"bovenste_ext_m_biceps_brachii","f":"m. biceps brachii","b":["Functie: flexie elleboog, krachtigste supinator van de onderarm; anteflexie schouder.","Innervatie: n. musculocutaneus.","Origo: caput longum – tuberculum supraglenoidale; caput breve – processus coracoideus. Insertie: tuberositas radii (+ aponeurosis bicipitalis).","Reflex: C5–C6."],"n":5},{"id":"bovenste_ext_m_brachialis","f":"m. brachialis","b":["Functie: krachtigste zuivere flexor van de elleboog (onafhankelijk van pro-/supinatie).","Innervatie: n. musculocutaneus (klein deel n. radialis).","Origo: distale helft voorzijde humerus. Insertie: tuberositas ulnae."],"n":2},{"id":"bovenste_ext_m_triceps_brachii","f":"m. triceps brachii","b":["Functie: extensie van de elleboog; caput longum ook extensie/adductie schouder.","Innervatie: n. radialis.","Origo: caput longum – tuberculum infraglenoidale; caput laterale en mediale – achterzijde humerus. Insertie: olecranon.","Reflex: C7."],"n":7},{"id":"bovenste_ext_m_pronator_teres","f":"m. pronator teres","b":["Functie: pronatie van de onderarm, zwakke flexie elleboog.","Innervatie: n. medianus (loopt tussen de twee koppen door).","Origo: epicondylus medialis + processus coronoideus ulnae. Insertie: midden laterale radius.","Oppervlakkige laag ventrale onderarm."],"n":0},{"id":"bovenste_ext_m_flexor_carpi_radialis","f":"m. flexor carpi radialis","b":["Functie: palmairflexie en radiaaldeviatie van de pols.","Innervatie: n. medianus.","Origo: epicondylus medialis. Insertie: basis MC II (en III)."],"n":1},{"id":"bovenste_ext_m_palmaris_longus","f":"m. palmaris longus","b":["Functie: palmairflexie van de pols; spant de aponeurosis palmaris.","Innervatie: n. medianus.","Origo: epicondylus medialis. Insertie: aponeurosis palmaris.","Ontbreekt bij ~15% van de mensen; pees vaak gebruikt als transplantaat."],"n":0},{"id":"bovenste_ext_m_flexor_carpi_ulnaris","f":"m. flexor carpi ulnaris","b":["Functie: palmairflexie en ulnairdeviatie van de pols.","Innervatie: n. ulnaris (uitzondering in de ventrale onderarm!).","Origo: epicondylus medialis + olecranon. Insertie: os pisiforme, hamulus ossis hamati, MC V."],"n":2},{"id":"bovenste_ext_m_flexor_digitorum_superficialis","f":"m. flexor digitorum superficialis","b":["Functie: flexie in de PIP-gewrichten (en MCP) van digiti II–V; helpt palmairflexie pols.","Innervatie: n. medianus.","Origo: epicondylus medialis, ulna, radius. Insertie: phalanx media II–V (pees splitst om de profunduspees).","Intermediaire laag."],"n":4},{"id":"bovenste_ext_m_flexor_digitorum_profundus","f":"m. flexor digitorum profundus","b":["Functie: flexie in de DIP-gewrichten (en PIP, MCP) van digiti II–V.","Innervatie: radiale deel (II–III) n. medianus (n. interosseus anterior); ulnaire deel (IV–V) n. ulnaris.","Origo: ulna en membrana interossea. Insertie: phalanx distalis II–V.","Diepe laag."],"n":2},{"id":"bovenste_ext_m_flexor_pollicis_longus","f":"m. flexor pollicis longus","b":["Functie: flexie van de duim, met name het IP-gewricht.","Innervatie: n. medianus (n. interosseus anterior).","Origo: voorzijde radius + membrana interossea. Insertie: phalanx distalis duim.","Diepe laag; loopt door de carpale tunnel."],"n":0},{"id":"bovenste_ext_m_pronator_quadratus","f":"m. pronator quadratus","b":["Functie: belangrijkste pronator van de onderarm.","Innervatie: n. medianus (n. interosseus anterior).","Vierkante spier tussen distale ulna en distale radius (ventraal), diepste laag."],"n":0},{"id":"bovenste_ext_m_brachioradialis","f":"m. brachioradialis","b":["Functie: flexie van de elleboog (vooral in mid-positie tussen pro- en supinatie). Functioneel een flexor, maar ligt bij de dorsale groep!","Innervatie: n. radialis.","Origo: crista supracondylaris lateralis humeri. Insertie: processus styloideus radii."],"n":2},{"id":"bovenste_ext_m_extensor_carpi_radialis_longus_en_brevis","f":"m. extensor carpi radialis longus en brevis","b":["Functie: dorsaalflexie en radiaaldeviatie van de pols.","Innervatie: n. radialis (brevis: ramus profundus).","Origo: crista supracondylaris lateralis/epicondylus lateralis. Insertie: basis MC II (longus) en MC III (brevis).","Brevis is vaak betrokken bij tenniselleboog."],"n":1},{"id":"bovenste_ext_m_extensor_digitorum","f":"m. extensor digitorum","b":["Functie: extensie van digiti II–V (MCP, via dorsale aponeurose ook PIP/DIP); helpt dorsaalflexie pols.","Innervatie: n. radialis (ramus profundus / n. interosseus posterior).","Origo: epicondylus lateralis. Insertie: dorsale aponeurose van digiti II–V."],"n":7},{"id":"bovenste_ext_m_extensor_digiti_minimi","f":"m. extensor digiti minimi","b":["Functie: extensie van de pink.","Innervatie: n. radialis (n. interosseus posterior).","Origo: epicondylus lateralis. Insertie: dorsale aponeurose digitus V."],"n":0},{"id":"bovenste_ext_m_extensor_carpi_ulnaris","f":"m. extensor carpi ulnaris","b":["Functie: dorsaalflexie en ulnairdeviatie van de pols.","Innervatie: n. radialis (n. interosseus posterior).","Origo: epicondylus lateralis + ulna. Insertie: basis MC V."],"n":1},{"id":"bovenste_ext_m_supinator","f":"m. supinator","b":["Functie: supinatie van de onderarm (vooral bij gestrekte elleboog).","Innervatie: n. radialis (ramus profundus, loopt dóór de spier).","Origo: epicondylus lateralis + crista supinatoria ulnae. Insertie: proximale radius.","Klinisch: compressie van de ramus profundus (supinatortunnel)."],"n":0},{"id":"bovenste_ext_m_abductor_pollicis_longus","f":"m. abductor pollicis longus","b":["Functie: abductie (en extensie) van de duim in het CMC-I-gewricht; radiaaldeviatie pols.","Innervatie: n. radialis (n. interosseus posterior).","Insertie: basis MC I. Begrenst de anatomische snuifdoos (palmair)."],"n":1},{"id":"bovenste_ext_m_extensor_pollicis_longus_en_brevis","f":"m. extensor pollicis longus en brevis","b":["Functie: extensie van de duim (longus: IP-gewricht; brevis: MCP-gewricht).","Innervatie: n. radialis (n. interosseus posterior).","Insertie: phalanx distalis (longus) / proximalis (brevis) van de duim.","Begrenzen de anatomische snuifdoos: longus dorsaal, brevis palmair."],"n":0},{"id":"bovenste_ext_m_extensor_indicis","f":"m. extensor indicis","b":["Functie: extensie van de wijsvinger (los van de andere vingers).","Innervatie: n. radialis (n. interosseus posterior).","Origo: distale ulna (dorsaal). Insertie: dorsale aponeurose digitus II."],"n":0},{"id":"bovenste_ext_thenarspieren","f":"thenarspieren","b":["Korte duimspieren in de duimmuis: m. abductor pollicis brevis, m. flexor pollicis brevis, m. opponens pollicis (+ m. adductor pollicis).","Functie: abductie, flexie, adductie en oppositie van de duim.","Innervatie: meeste door n. medianus (ramus recurrens); m. adductor pollicis door n. ulnaris.","Atrofie bij carpaletunnelsyndroom."],"n":2},{"id":"bovenste_ext_hypothenarspieren","f":"hypothenarspieren","b":["Korte pinkspieren in de pinkmuis: m. abductor digiti minimi, m. flexor digiti minimi brevis, m. opponens digiti minimi.","Functie: abductie, flexie en oppositie van de pink.","Innervatie: n. ulnaris (ramus profundus)."],"n":0},{"id":"bovenste_ext_mm_interossei_en_mm_lumbricales","f":"mm. interossei en mm. lumbricales","b":["Functie (beide): flexie in de MCP-gewrichten en extensie in de PIP- en DIP-gewrichten van digiti II–V (‘lumbrical grip’).","Interossei dorsales: spreiden (abductie, DAB); interossei palmares: sluiten (adductie, PAD).","Innervatie: interossei → n. ulnaris; lumbricales I–II → n. medianus, III–IV → n. ulnaris."],"n":0}]},{"name":"Zenuwen","cards":[{"id":"bovenste_ext_n_accessorius_n_xi_arm","f":"n. accessorius (N. XI) – arm","b":["Hersenzenuw XI (spinaal deel uit C1–C5).","Motorisch: m. trapezius en m. sternocleidomastoideus.","Loopt oppervlakkig door de laterale halsdriehoek → kwetsbaar bij lymfeklierbiopten (uitval: schouder hangt, moeite met elevatie)."],"n":0},{"id":"bovenste_ext_plexus_brachialis","f":"plexus brachialis","b":["Gevormd door de ventrale rami van C5–T1.","Opbouw: radices → trunci (superior C5–6, medius C7, inferior C8–T1) → divisiones → fasciculi (lateralis, medialis, posterior) → eindtakken.","Eindtakken: n. musculocutaneus, medianus, ulnaris, radialis, axillaris."],"n":5},{"id":"bovenste_ext_truncus_superior_medius_en_inferior","f":"truncus superior, medius en inferior","b":["Truncus superior: C5 + C6. Truncus medius: C7. Truncus inferior: C8 + T1.","Liggen in de achterste scalenuspoort (tussen m. scalenus anterior en medius) samen met de a. subclavia.","Letsel truncus superior → Erb-parese (‘waiter’s tip’); truncus inferior → Klumpke-parese (klauwhand)."],"n":0},{"id":"bovenste_ext_fasciculus_lateralis_medialis_en_posterior","f":"fasciculus lateralis, medialis en posterior","b":["Genoemd naar hun ligging t.o.v. de a. axillaris.","Lateralis → n. musculocutaneus + laterale wortel n. medianus.","Medialis → n. ulnaris + mediale wortel n. medianus (+ huidzenuwen arm/onderarm medialis). Posterior → n. axillaris + n. radialis."],"n":0},{"id":"bovenste_ext_n_musculocutaneus_c5_c7","f":"n. musculocutaneus (C5–C7)","b":["Uit de fasciculus lateralis; doorboort de m. coracobrachialis.","Motorisch: ventrale bovenarmspieren (m. coracobrachialis, m. biceps brachii, m. brachialis).","Sensibel: als n. cutaneus antebrachii lateralis de laterale onderarm."],"n":8},{"id":"bovenste_ext_n_medianus_c6_t1","f":"n. medianus (C6–T1)","b":["Uit fasciculus lateralis + medialis; loopt met de a. brachialis door de sulcus bicipitalis medialis en fossa cubiti, dan door de carpale tunnel.","Motorisch: ventrale onderarmspieren behalve m. flexor carpi ulnaris en ulnaire deel m. flexor digitorum profundus; bijna alle thenarspieren; lumbricales I–II.","Sensibel: palmair duim, wijs-, middel- en halve ringvinger.","Klinisch: carpaletunnelsyndroom; hoge laesie → ‘eedhand’."],"n":7},{"id":"bovenste_ext_n_ulnaris_c8_t1","f":"n. ulnaris (C8–T1)","b":["Uit fasciculus medialis; loopt achter de epicondylus medialis (sulcus n. ulnaris) en via het kanaal van Guyon naar de hand.","Motorisch: m. flexor carpi ulnaris, ulnaire deel m. flexor digitorum profundus, meeste intrinsieke handspieren (hypothenar, interossei, lumbricales III–IV, m. adductor pollicis).","Sensibel: pink en halve ringvinger.","Laesie → klauwhand, teken van Froment."],"n":10},{"id":"bovenste_ext_n_radialis_c5_t1","f":"n. radialis (C5–T1)","b":["Uit fasciculus posterior; loopt om de humerus in de sulcus nervi radialis, splitst bij de elleboog in ramus superficialis (sensibel) en profundus (motorisch).","Motorisch: alle dorsale boven- en onderarmspieren (triceps, brachioradialis, extensoren).","Sensibel: dorsale arm/onderarm en dorsoradiale hand (snuifdoos).","Laesie (humerusschachtfractuur) → dropshand."],"n":8},{"id":"bovenste_ext_n_axillaris_c5_c6","f":"n. axillaris (C5–C6)","b":["Uit fasciculus posterior; loopt met de a. circumflexa humeri posterior door de laterale okselspleet om het collum chirurgicum.","Motorisch: m. deltoideus en m. teres minor.","Sensibel: huid over de m. deltoideus (‘legerembleem’).","Kwetsbaar bij schouderluxatie en collum-chirurgicumfractuur."],"n":10},{"id":"bovenste_ext_n_thoracodorsalis","f":"n. thoracodorsalis","b":["Uit fasciculus posterior (C6–C8).","Motorisch: m. latissimus dorsi.","Loopt langs de laterale thoraxwand mee met de a. thoracodorsalis."],"n":3},{"id":"bovenste_ext_n_thoracicus_longus","f":"n. thoracicus longus","b":["Direct uit de radices C5–C7; loopt op de buitenzijde van de m. serratus anterior.","Motorisch: m. serratus anterior.","Kwetsbaar bij okselchirurgie → scapula alata."],"n":2},{"id":"bovenste_ext_n_cutaneus_brachii_medialis","f":"n. cutaneus brachii medialis","b":["Sensibele zenuw uit de fasciculus medialis (C8–T1).","Verzorgt de huid van de mediale zijde van de bovenarm.","Communiceert met de n. intercostobrachialis (T2)."],"n":0},{"id":"bovenste_ext_n_cutaneus_antebrachii_medialis","f":"n. cutaneus antebrachii medialis","b":["Sensibele zenuw uit de fasciculus medialis (C8–T1).","Verzorgt de huid van de mediale (ulnaire) zijde van de onderarm.","Loopt mee met de v. basilica."],"n":0},{"id":"bovenste_ext_n_cutaneus_antebrachii_lateralis","f":"n. cutaneus antebrachii lateralis","b":["Sensibele eindtak (voortzetting) van de n. musculocutaneus (C5–C6).","Verzorgt de huid van de laterale (radiale) zijde van de onderarm.","Komt lateraal van de bicepspees in de fossa cubiti oppervlakkig te liggen."],"n":0}]},{"name":"Bloedvaten","cards":[{"id":"bovenste_ext_a_subclavia","f":"a. subclavia","b":["Rechts uit de truncus brachiocephalicus, links direct uit de aortaboog.","Loopt door de achterste scalenuspoort over de 1e rib; wordt aan de laterale rand van rib 1 de a. axillaris.","Takken o.a. a. vertebralis, a. thoracica interna, truncus thyrocervicalis en costocervicalis."],"n":7},{"id":"bovenste_ext_a_axillaris","f":"a. axillaris","b":["Voortzetting van de a. subclavia vanaf de laterale rand van rib 1 tot de onderrand van de m. teres major.","Verzorgt oksel, schouder en laterale thoraxwand (o.a. a. thoracoacromialis, a. thoracica lateralis, a. subscapularis, aa. circumflexae humeri).","Omgeven door de fasciculi van de plexus brachialis."],"n":4},{"id":"bovenste_ext_a_brachialis","f":"a. brachialis","b":["Voortzetting van de a. axillaris vanaf de onderrand m. teres major.","Loopt in de sulcus bicipitalis medialis met de n. medianus; splitst in de fossa cubiti in a. radialis en a. ulnaris.","Palpabel mediaal van de bicepspees in de elleboogplooi (bloeddrukmeting)."],"n":2},{"id":"bovenste_ext_a_profunda_brachii","f":"a. profunda brachii","b":["Tak van de a. brachialis in de bovenarm.","Loopt met de n. radialis in de sulcus nervi radialis achter om de humerus.","Verzorgt de m. triceps brachii; draagt bij aan het anastomosenetwerk rond de elleboog."],"n":2},{"id":"bovenste_ext_a_radialis","f":"a. radialis","b":["Eindtak van de a. brachialis, loopt aan de radiale zijde van de onderarm.","Gaat door de anatomische snuifdoos naar de diepe handpalm → arcus palmaris profundus.","Palpabel aan de pols lateraal van de pees van de m. flexor carpi radialis (polsslag)."],"n":5},{"id":"bovenste_ext_a_ulnaris","f":"a. ulnaris","b":["Grootste eindtak van de a. brachialis, loopt aan de ulnaire zijde van de onderarm.","Gaat via het kanaal van Guyon naar de hand → vooral arcus palmaris superficialis.","Geeft de a. interossea communis af. Palpabel radiaal van het os pisiforme."],"n":5},{"id":"bovenste_ext_arcus_palmaris_superficialis_en_profundus","f":"arcus palmaris superficialis en profundus","b":["Superficialis: vooral gevormd door de a. ulnaris, ligt direct onder de aponeurosis palmaris (distaler).","Profundus: vooral gevormd door de a. radialis, ligt diep op de metacarpalia (proximaler).","Takken verzorgen de vingers (aa. digitales). Test van Allen controleert de collaterale doorbloeding."],"n":0},{"id":"bovenste_ext_v_subclavia_diep","f":"v. subclavia (diep)","b":["Voortzetting van de v. axillaris vanaf de laterale rand van rib 1.","Loopt vóór de m. scalenus anterior (voorste scalenuspoort), dus vóór de arterie.","Vormt met de v. jugularis interna de v. brachiocephalica (veneuze hoek: instroom ductus thoracicus links)."],"n":0},{"id":"bovenste_ext_v_axillaris_diep","f":"v. axillaris (diep)","b":["Ontstaat uit samenvloeiing van de vv. brachiales en de v. basilica.","Ontvangt de v. cephalica.","Wordt aan de laterale rand van rib 1 de v. subclavia."],"n":0},{"id":"bovenste_ext_v_cephalica_oppervlakkig","f":"v. cephalica (oppervlakkig)","b":["Oppervlakkige vene aan de laterale (radiale) zijde van de arm.","Loopt in de sulcus deltoideopectoralis naar de v. axillaris.","Ontstaat uit het dorsale veneuze netwerk van de hand."],"n":0},{"id":"bovenste_ext_vv_brachiales_diep","f":"vv. brachiales (diep)","b":["Begeleidende venen (venae comitantes) van de a. brachialis.","Ontstaan uit de vv. radiales en ulnares.","Vormen samen met de v. basilica de v. axillaris."],"n":0},{"id":"bovenste_ext_v_basilica_oppervlakkig","f":"v. basilica (oppervlakkig)","b":["Oppervlakkige vene aan de mediale (ulnaire) zijde van de arm.","Doorboort halverwege de bovenarm de fascie en mondt uit in de vv. brachiales/v. axillaris.","Loopt mee met de n. cutaneus antebrachii medialis."],"n":0},{"id":"bovenste_ext_v_mediana_cubiti_oppervlakkig","f":"v. mediana cubiti (oppervlakkig)","b":["Oppervlakkige verbindingsvene in de elleboogplooi tussen v. cephalica en v. basilica.","Ligt boven de aponeurosis bicipitalis (die de a. brachialis en n. medianus beschermt).","Standaardplek voor venapunctie (bloedafname)."],"n":0},{"id":"bovenste_ext_vv_radiales_en_vv_ulnares_diep","f":"vv. radiales en vv. ulnares (diep)","b":["Paarsgewijze begeleidende venen van de a. radialis en a. ulnaris.","Draineren de diepe structuren van onderarm en hand.","Vloeien samen tot de vv. brachiales."],"n":0},{"id":"bovenste_ext_diepe_vs_oppervlakkige_venen_arm","f":"diepe vs. oppervlakkige venen (arm)","b":["Diepe venen (vv. profundae) lopen als venae comitantes mee met de arteriën, onder de fascie.","Oppervlakkige venen (vv. superficiales: cephalica, basilica, mediana cubiti) lopen subcutaan, zonder arterie.","Ze zijn verbonden via vv. perforantes."],"n":1}]}]},{"name":"Onderste extremiteit","groups":[{"name":"Skelet","cards":[{"id":"onderste_ext_pelvis","f":"pelvis","b":["Bekken: gevormd door de twee ossa coxae, het os sacrum (en os coccygis).","Verbindingen: SI-gewrichten (dorsaal) en symphysis pubica (ventraal).","Draagt het gewicht van de romp over op de benen; omsluit de bekkenorganen."],"n":0},{"id":"onderste_ext_os_coxae","f":"os coxae","b":["Heupbeen: ontstaat uit vergroeiing van os ilium, os ischii en os pubis (in het acetabulum, rond de puberteit).","Draagt het acetabulum (heupkom).","Articuleert met het sacrum (SI-gewricht), het andere os coxae (symfyse) en de femurkop."],"n":1},{"id":"onderste_ext_os_ilium","f":"os ilium","b":["Darmbeen: het bovenste, waaiervormige deel van het os coxae.","Belangrijke structuren: crista iliaca, spina iliaca anterior superior (SIAS) en inferior, spina iliaca posterior.","Binnenzijde: fossa iliaca (origo m. iliacus)."],"n":2},{"id":"onderste_ext_crista_iliaca","f":"crista iliaca","b":["Bovenrand (kam) van het os ilium, loopt van SIAS tot spina iliaca posterior superior.","Goed palpabel; de lijn tussen beide cristae ligt ter hoogte van L4 (oriëntatie bij lumbaalpunctie).","Aanhechting buikspieren, m. latissimus dorsi, m. quadratus lumborum."],"n":0},{"id":"onderste_ext_spina_iliaca_anterior_superior_sias","f":"spina iliaca anterior superior (SIAS)","b":["Voorste uiteinde van de crista iliaca; goed palpabel.","Origo van m. sartorius en m. tensor fasciae latae; aanhechting lig. inguinale.","Oriëntatiepunt bij beenlengtemeting en de lies (n. cutaneus femoris lateralis loopt er vlak langs)."],"n":2},{"id":"onderste_ext_os_ischii","f":"os ischii","b":["Zitbeen: dorsaal-caudale deel van het os coxae.","Belangrijkste onderdeel: tuber ischiadicum; daarnaast spina ischiadica.","Begrenst samen met het os pubis het foramen obturatum."],"n":1},{"id":"onderste_ext_tuber_ischiadicum","f":"tuber ischiadicum","b":["Zitknobbel van het os ischii: daar zit je op.","Origo van de hamstrings (m. semitendinosus, m. semimembranosus, caput longum m. biceps femoris) en deel van de m. adductor magnus.","Palpabel in zit; avulsiefractuur bij sporters."],"n":3},{"id":"onderste_ext_os_pubis","f":"os pubis","b":["Schaambeen: ventraal-caudaal deel van het os coxae.","Vormt met het andere os pubis de symphysis pubica.","Origo van de adductoren (m. pectineus, m. adductor longus/brevis, m. gracilis)."],"n":2},{"id":"onderste_ext_acetabulum","f":"acetabulum","b":["Diepe heupkom, gevormd door os ilium, ischii en pubis.","Facies lunata (hoefijzervormig kraakbeen) + labrum acetabulare.","In de fossa acetabuli ontspringt het lig. capitis femoris."],"n":4},{"id":"onderste_ext_symphysis_pubica","f":"symphysis pubica","b":["Kraakbenige verbinding (amfiartrose) tussen beide ossa pubis met discus interpubicus.","Nauwelijks beweeglijk; verweekt iets tijdens zwangerschap.","Ventrale afsluiting van de bekkenring."],"n":0},{"id":"onderste_ext_foramen_obturatum","f":"foramen obturatum","b":["Grote opening in het os coxae, begrensd door os pubis en os ischii.","Grotendeels afgesloten door de membrana obturatoria.","Bovenaan laat de canalis obturatorius de n., a. en v. obturatoria door."],"n":2},{"id":"onderste_ext_femur","f":"femur","b":["Dijbeen: langste en sterkste bot van het lichaam.","Proximaal: caput, collum, trochanter major en minor. Distaal: condylus medialis en lateralis, epicondylen.","Collum-schachthoek ca. 125°; anteversie ca. 15°."],"n":9},{"id":"onderste_ext_caput_en_collum_femoris","f":"caput en collum femoris","b":["Caput: bolvormige kop, articuleert met het acetabulum.","Collum: hals tussen kop en schacht.","Collumfractuur (ouderen, val) kan de a. circumflexa femoris medialis beschadigen → avasculaire kopnecrose."],"n":8},{"id":"onderste_ext_trochanter_major_en_minor","f":"trochanter major en minor","b":["Trochanter major: lateraal, palpabel; aanhechting m. gluteus medius en minimus en diepe exorotatoren (m. piriformis, mm. obturatorii, mm. gemelli).","Trochanter minor: mediaal-dorsaal; aanhechting m. iliopsoas.","Bursa trochanterica ligt over de trochanter major."],"n":6},{"id":"onderste_ext_condylus_lateralis_en_medialis_femur","f":"condylus lateralis en medialis (femur)","b":["Twee gewrichtsknobbels aan het distale femur.","Articuleren met het tibiaplateau; ventraal samen het facies patellaris.","Daartussen dorsaal de fossa intercondylaris (aanhechting kruisbanden)."],"n":3},{"id":"onderste_ext_epicondylus_lateralis_en_medialis_femur","f":"epicondylus lateralis en medialis (femur)","b":["Uitsteeksels op de condylen, palpabel aan weerszijden van de knie.","Aanhechting van de collaterale knieligamenten.","Boven de epicondylus medialis: tuberculum adductorium (insertie m. adductor magnus)."],"n":3},{"id":"onderste_ext_patella","f":"patella","b":["Knieschijf: grootste sesambeen van het lichaam, in de pees van de m. quadriceps femoris.","Vergroot de hefboomarm van de quadriceps.","Articuleert met het facies patellaris femoris; goed palpabel."],"n":5},{"id":"onderste_ext_tibia","f":"tibia","b":["Scheenbeen: mediale, gewichtdragende onderbeenbot.","Proximaal: condylus medialis en lateralis (tibiaplateau), tuberositas tibiae. Distaal: malleolus medialis.","Voorrand (margo anterior) subcutaan palpabel → open fracturen komen veel voor."],"n":15},{"id":"onderste_ext_condylus_lateralis_en_medialis_tibiae_tibiaplat","f":"condylus lateralis en medialis tibiae (tibiaplateau)","b":["Vlakke gewrichtsvlakken bovenop de tibia voor de femurcondylen.","Daarop liggen de menisci.","Tussen beide de eminentia intercondylaris (aanhechting kruisbanden en menisci)."],"n":3},{"id":"onderste_ext_tuberositas_tibiae","f":"tuberositas tibiae","b":["Ruw uitsteeksel aan de voorzijde van de proximale tibia.","Aanhechting van het lig. patellae (dus van de m. quadriceps femoris).","Ziekte van Osgood-Schlatter bij adolescenten (tractie-apofysitis)."],"n":4},{"id":"onderste_ext_malleolus_medialis","f":"malleolus medialis","b":["Binnenenkel: distaal uitsteeksel van de tibia.","Vormt de mediale wand van de enkelvork.","Aanhechting lig. deltoideum; erachter loopt de tarsale tunnel."],"n":2},{"id":"onderste_ext_fibula","f":"fibula","b":["Kuitbeen: dun laterale onderbeenbot, nauwelijks gewichtdragend.","Proximaal caput fibulae, distaal malleolus lateralis.","Origo van vele onderbeenspieren; membrana interossea verbindt hem met de tibia."],"n":9},{"id":"onderste_ext_caput_fibulae","f":"caput fibulae","b":["Kop van de fibula, lateraal net onder de knie; palpabel.","Aanhechting lig. collaterale fibulare en m. biceps femoris.","De n. fibularis communis loopt eromheen langs het collum fibulae → kwetsbaar (klapvoet)."],"n":2},{"id":"onderste_ext_malleolus_lateralis","f":"malleolus lateralis","b":["Buitenenkel: distaal uiteinde van de fibula.","Reikt verder naar distaal dan de malleolus medialis.","Aanhechting van de laterale enkelbanden; achterlangs lopen de fibularispezen."],"n":2},{"id":"onderste_ext_ossa_tarsalia","f":"ossa tarsalia","b":["7 voetwortelbeentjes: talus, calcaneus, os naviculare, os cuboideum, ossa cuneiformia mediale, intermedium en laterale.","Talus articuleert met de enkelvork; calcaneus vormt de hiel.","Samen dragen ze het lichaamsgewicht en vormen de voetgewelven."],"n":0},{"id":"onderste_ext_talus","f":"talus","b":["Sprongbeen: bovenste voetwortelbeen, ligt in de enkelvork (bovenste spronggewricht).","Heeft geen spieraanhechtingen.","Draagt het gewicht van de tibia over op calcaneus en naviculare."],"n":5},{"id":"onderste_ext_calcaneus","f":"calcaneus","b":["Hielbeen: grootste voetwortelbeen.","Aanhechting van de achillespees (tuber calcanei).","Articuleert met de talus (onderste spronggewricht) en het os cuboideum. Fractuur bij val van hoogte."],"n":5},{"id":"onderste_ext_os_naviculare_os_cuboideum_ossa_cuneiformia","f":"os naviculare, os cuboideum, ossa cuneiformia","b":["Os naviculare: mediaal, tussen talus en de cuneiformia; aanhechting m. tibialis posterior (tuberositas, palpabel).","Os cuboideum: lateraal, tussen calcaneus en MT IV–V; groeve voor de pees van m. fibularis longus.","Ossa cuneiformia mediale, intermedium, laterale: tussen naviculare en MT I–III."],"n":6},{"id":"onderste_ext_ossa_metatarsalia_i_v","f":"ossa metatarsalia I–V","b":["Middenvoetsbeentjes; MT I is het kortst en dikst.","Basis van MT V (tuberositas): aanhechting m. fibularis brevis; avulsiefractuur bij inversietrauma.","Mars- of stressfracturen vooral in MT II–III."],"n":0},{"id":"onderste_ext_digiti_pedis_i_hallux_v_phalanges","f":"digiti pedis I (hallux) – V: phalanges","b":["Grote teen (hallux) heeft 2 phalanges, de overige tenen 3 (proximalis, media, distalis).","Gewrichten: MTP en IP (PIP/DIP).","Hallux valgus = afwijking van de grote teen naar lateraal."],"n":0}]},{"name":"Gewrichten","cards":[{"id":"onderste_ext_articulatio_sacro_iliaca_si_gewricht","f":"articulatio sacro-iliaca (SI-gewricht)","b":["Tussen os sacrum en os ilium.","Deels synoviaal (vlak), deels syndesmose; zeer weinig beweging (nutatie).","Verstevigd door zeer sterke ligamenten (ligg. sacro-iliaca); draagt de romplast over op het bekken."],"n":0},{"id":"onderste_ext_articulatio_coxae_heupgewricht","f":"articulatio coxae (heupgewricht)","b":["Kogelgewricht (‘notengewricht’) tussen caput femoris en acetabulum.","Bewegingen: flexie/extensie, abductie/adductie, endo-/exorotatie.","Zeer stabiel door diepe kom, labrum en sterke kapselbanden (lig. iliofemorale, pubofemorale, ischiofemorale)."],"n":15},{"id":"onderste_ext_lig_capitis_femoris","f":"ligamentum capitis femoris","b":["Intra-articulaire band van de fossa acetabuli naar de fovea capitis femoris.","Draagt weinig bij aan stabiliteit.","Bevat een kleine arterie (tak a. obturatoria) die bij kinderen belangrijk is voor de doorbloeding van de femurkop."],"n":3},{"id":"onderste_ext_labrum_acetabulare","f":"labrum acetabulare","b":["Fibrocartilagineuze ring om de rand van het acetabulum.","Verdiept de kom en sluit de gewrichtsruimte af (zuigeffect).","Scheuren bij heupimpingement (FAI)."],"n":1},{"id":"onderste_ext_bursa_iliopectinea","f":"bursa iliopectinea","b":["Slijmbeurs tussen de m. iliopsoas en het heupkapsel/eminentia iliopectinea.","Grootste bursa rond de heup; staat vaak in verbinding met het heupgewricht.","Bursitis geeft liespijn."],"n":0},{"id":"onderste_ext_articulatio_genus_kniegewricht","f":"articulatio genus (kniegewricht)","b":["Tussen femurcondylen, tibiaplateau en patella; grootste gewricht.","Rolglijscharniergewricht (bicondylair): flexie/extensie en in flexie ook endo-/exorotatie.","Stabiliteit door kruisbanden, collaterale banden, menisci en spieren."],"n":11},{"id":"onderste_ext_meniscus_medialis_en_lateralis","f":"meniscus medialis en lateralis","b":["Halvemaanvormige fibrocartilagineuze schijven op het tibiaplateau.","Vergroten de congruentie, schokdemping en gewichtsverdeling.","Meniscus medialis is C-vormig en vergroeid met het lig. collaterale tibiale → minder beweeglijk → vaker gescheurd. Lateralis is meer O-vormig."],"n":0},{"id":"onderste_ext_lig_cruciatum_anterius_en_posterius","f":"ligamentum cruciatum anterius en posterius","b":["Voorste kruisband (VKB): van tibia (ventraal) naar laterale femurcondyl; voorkomt naar voren schuiven van de tibia (voorste schuifladetest, Lachman).","Achterste kruisband (AKB): van tibia (dorsaal) naar mediale femurcondyl; voorkomt naar achteren schuiven van de tibia.","VKB-ruptuur bij draaitrauma; ‘unhappy triad’ = VKB + mediale meniscus + mediale collaterale band."],"n":4},{"id":"onderste_ext_lig_collaterale_tibiale_en_fibulare","f":"ligamentum collaterale tibiale en fibulare","b":["Collaterale tibiale (mediale band): breed, vergroeid met kapsel en meniscus medialis; voorkomt valgus.","Collaterale fibulare (laterale band): koordvormig, los van de meniscus; van epicondylus lateralis naar caput fibulae; voorkomt varus.","Gespannen in extensie."],"n":0},{"id":"onderste_ext_pees_m_quadriceps_femoris_en_lig_patellae","f":"pees m. quadriceps femoris en ligamentum patellae","b":["De quadricepspees hecht aan de bovenpool van de patella.","Het lig. patellae loopt van de onderpool van de patella naar de tuberositas tibiae (functioneel de voortzetting van de pees).","Klopje op het lig. patellae → kniepeesreflex (L3–L4)."],"n":2},{"id":"onderste_ext_bursae_van_de_knie_suprapatellaris_prepatellari","f":"bursae van de knie (suprapatellaris, prepatellaris, infrapatellaris)","b":["Bursa suprapatellaris: onder de quadricepspees boven de patella; staat in open verbinding met het kniegewricht.","Bursa prepatellaris: subcutaan vóór de patella (bursitis = ‘tegelzetterknie’).","Bursa infrapatellaris (superficialis/profunda): rond het lig. patellae."],"n":0},{"id":"onderste_ext_articulatio_tibiofibularis_superior","f":"articulatio tibiofibularis (superior)","b":["Tussen caput fibulae en condylus lateralis tibiae.","Vlak synoviaal gewricht; zeer weinig beweging.","Ligt buiten het kniegewricht."],"n":2},{"id":"onderste_ext_membrana_interossea_cruris","f":"membrana interossea cruris","b":["Bindweefselplaat tussen tibia en fibula.","Scheidt het voorste en achterste compartiment van het onderbeen.","Origo van diepe onderbeenspieren (o.a. m. tibialis anterior en posterior)."],"n":1},{"id":"onderste_ext_syndesmosis_tibiofibularis_art_tibiofibularis_i","f":"syndesmosis tibiofibularis (art. tibiofibularis inferior)","b":["Bindweefselverbinding tussen distale tibia en fibula.","Houdt de enkelvork bij elkaar.","Letsel bij hoge enkelfracturen (Weber C)."],"n":0},{"id":"onderste_ext_articulatio_talocruralis_bovenste_spronggewrich","f":"articulatio talocruralis (bovenste spronggewricht)","b":["Tussen de enkelvork (tibia + fibula) en de trochlea tali.","Scharniergewricht: dorsaalflexie en plantairflexie.","Meest stabiel in dorsaalflexie (trochlea is ventraal breder)."],"n":4},{"id":"onderste_ext_lig_collaterale_mediale_lig_deltoideum","f":"ligamentum collaterale mediale (lig. deltoideum)","b":["Waaiervormige, zeer sterke band van malleolus medialis naar talus, calcaneus en naviculare.","Voorkomt eversie (valgus) van de enkel.","Scheurt zelden; eerder een avulsiefractuur van de malleolus medialis."],"n":5},{"id":"onderste_ext_lig_collaterale_laterale_enkel","f":"ligamentum collaterale laterale (enkel)","b":["Drie delen: lig. talofibulare anterius, lig. calcaneofibulare, lig. talofibulare posterius.","Voorkomt inversie (supinatie) van de enkel.","Lig. talofibulare anterius scheurt het vaakst (inversietrauma, ‘verzwikte enkel’)."],"n":3},{"id":"onderste_ext_articulatio_subtalaris_en_talocalcaneonavicular","f":"articulatio subtalaris en talocalcaneonavicularis (onderste spronggewricht)","b":["Tussen talus, calcaneus en os naviculare.","Bewegingen: inversie en eversie (supinatie/pronatie van de voet).","Functioneel één gewricht met een schuine as."],"n":1},{"id":"onderste_ext_mtp_gewrichten_en_voetgewelven","f":"MTP-gewrichten en voetgewelven","b":["MTP-gewrichten: tussen metatarsalia en proximale phalanges; flexie/extensie (en beperkt ab-/adductie).","Longitudinaal voetgewelf (mediaal hoger dan lateraal) en dwars (transversaal) voetgewelf.","Gewelven worden ondersteund door botvorm, ligamenten, fascia plantaris en spieren (o.a. m. tibialis posterior, m. fibularis longus)."],"n":0}]},{"name":"Spieren","cards":[{"id":"onderste_ext_m_iliopsoas_m_iliacus_en_m_psoas_major","f":"m. iliopsoas (m. iliacus en m. psoas major)","b":["Functie: krachtigste flexor van de heup (anteflexie); psoas ook lateroflexie lumbale wervelkolom.","Innervatie: n. femoralis (iliacus) en directe takken L1–L3 (psoas).","Origo: psoas – wervellichamen/processus T12–L4; iliacus – fossa iliaca. Insertie: trochanter minor.","Loopt door de lacuna musculorum onder het lig. inguinale."],"n":3},{"id":"onderste_ext_m_quadriceps_femoris","f":"m. quadriceps femoris","b":["4 koppen: m. rectus femoris, m. vastus medialis, lateralis en intermedius.","Functie: extensie van de knie; rectus femoris ook flexie van de heup (twee-gewrichtsspier).","Innervatie: n. femoralis.","Insertie via patella en lig. patellae op de tuberositas tibiae. Rectus femoris: origo SIAI."],"n":6},{"id":"onderste_ext_m_sartorius","f":"m. sartorius","b":["Functie: flexie, abductie en exorotatie heup + flexie knie (‘kleermakerszit’).","Innervatie: n. femoralis.","Origo: SIAS. Insertie: pes anserinus (mediaal proximale tibia).","Langste spier van het lichaam; dak van het kanaal van Hunter."],"n":3},{"id":"onderste_ext_m_semitendinosus","f":"m. semitendinosus","b":["Hamstring. Functie: extensie heup, flexie en endorotatie knie.","Innervatie: n. tibialis (deel n. ischiadicus).","Origo: tuber ischiadicum. Insertie: pes anserinus.","Lange dunne pees (‘tendinosus’); gebruikt bij VKB-reconstructie."],"n":5},{"id":"onderste_ext_m_semimembranosus","f":"m. semimembranosus","b":["Hamstring. Functie: extensie heup, flexie en endorotatie knie.","Innervatie: n. tibialis (deel n. ischiadicus).","Origo: tuber ischiadicum. Insertie: dorsomediaal condylus medialis tibiae.","Breed, vliezig origo (‘membranosus’); ligt diep van de semitendinosus."],"n":2},{"id":"onderste_ext_m_biceps_femoris","f":"m. biceps femoris","b":["Hamstring (lateraal). Functie: extensie heup (caput longum), flexie en exorotatie knie.","Innervatie: caput longum – n. tibialis; caput breve – n. fibularis communis.","Origo: caput longum – tuber ischiadicum; caput breve – linea aspera femoris. Insertie: caput fibulae."],"n":7},{"id":"onderste_ext_m_pectineus","f":"m. pectineus","b":["Functie: adductie en flexie van de heup.","Innervatie: n. femoralis (en vaak n. obturatorius) – dubbele innervatie.","Origo: pecten ossis pubis. Insertie: linea pectinea femoris.","Vormt de bodem van de trigonum femorale."],"n":2},{"id":"onderste_ext_m_adductor_longus","f":"m. adductor longus","b":["Functie: adductie (en flexie) van de heup.","Innervatie: n. obturatorius.","Origo: os pubis (nabij symfyse). Insertie: midden linea aspera.","Mediale grens van de trigonum femorale; liesblessure bij voetballers."],"n":1},{"id":"onderste_ext_m_gracilis","f":"m. gracilis","b":["Functie: adductie heup, flexie en endorotatie knie.","Innervatie: n. obturatorius.","Origo: os pubis (ramus inferior). Insertie: pes anserinus.","Enige adductor die over de knie loopt."],"n":5},{"id":"onderste_ext_m_adductor_brevis","f":"m. adductor brevis","b":["Functie: adductie van de heup.","Innervatie: n. obturatorius.","Origo: os pubis. Insertie: proximale linea aspera.","Ligt tussen de voorste en achterste tak van de n. obturatorius."],"n":0},{"id":"onderste_ext_m_adductor_magnus","f":"m. adductor magnus","b":["Functie: adductie heup; adductordeel ook flexie, hamstringdeel extensie.","Innervatie: dubbel – n. obturatorius (adductordeel) en n. tibialis (hamstringdeel).","Origo: os pubis, os ischii, tuber ischiadicum. Insertie: linea aspera en tuberculum adductorium.","Opening in de insertie = hiatus adductorius (a./v. femoralis naar de fossa poplitea)."],"n":1},{"id":"onderste_ext_m_gluteus_maximus","f":"m. gluteus maximus","b":["Functie: extensie (retroversie) en exorotatie van de heup; belangrijk bij opstaan, traplopen.","Innervatie: n. gluteus inferior.","Origo: os ilium (dorsaal), sacrum, coccyx. Insertie: tractus iliotibialis en tuberositas glutea."],"n":7},{"id":"onderste_ext_m_gluteus_medius","f":"m. gluteus medius","b":["Functie: abductie van de heup; houdt het bekken horizontaal bij staan op één been.","Innervatie: n. gluteus superior.","Origo: buitenzijde os ilium. Insertie: trochanter major.","Uitval → teken van Trendelenburg (bekken zakt aan de andere kant)."],"n":3},{"id":"onderste_ext_m_gluteus_minimus","f":"m. gluteus minimus","b":["Functie: abductie en endorotatie van de heup; stabiliseert het bekken.","Innervatie: n. gluteus superior.","Origo: buitenzijde os ilium (diep van gluteus medius). Insertie: trochanter major (ventraal)."],"n":0},{"id":"onderste_ext_m_tensor_fasciae_latae","f":"m. tensor fasciae latae","b":["Functie: abductie, flexie en endorotatie heup; spant de tractus iliotibialis (stabiliseert knie in extensie).","Innervatie: n. gluteus superior.","Origo: SIAS. Insertie: tractus iliotibialis."],"n":0},{"id":"onderste_ext_m_piriformis","f":"m. piriformis","b":["Functie: exorotatie (en abductie in flexie) van de heup.","Innervatie: directe takken plexus sacralis (S1–S2).","Origo: voorzijde os sacrum. Insertie: trochanter major.","Loopt door het foramen ischiadicum majus en verdeelt dat in foramen supra- en infrapiriforme."],"n":1},{"id":"onderste_ext_m_obturatorius_internus_en_externus","f":"m. obturatorius internus en externus","b":["Functie: exorotatie van de heup.","Innervatie: internus – n. ad m. obturatorium internum (plexus sacralis); externus – n. obturatorius.","Origo: binnen- resp. buitenzijde membrana obturatoria. Insertie: fossa trochanterica / trochanter major."],"n":2},{"id":"onderste_ext_mm_gemelli_superior_en_inferior","f":"mm. gemelli superior en inferior","b":["Functie: exorotatie van de heup.","Innervatie: superior – zoals m. obturatorius internus; inferior – zoals m. quadratus femoris (plexus sacralis).","Kleine spiertjes boven en onder de pees van de m. obturatorius internus; insertie trochanter major."],"n":0},{"id":"onderste_ext_m_quadratus_femoris","f":"m. quadratus femoris","b":["Functie: exorotatie (en adductie) van de heup.","Innervatie: n. ad m. quadratum femoris (plexus sacralis).","Origo: tuber ischiadicum. Insertie: crista intertrochanterica.","Onderste van de diepe exorotatoren."],"n":2},{"id":"onderste_ext_m_tibialis_anterior","f":"m. tibialis anterior","b":["Functie: dorsaalflexie van de enkel en inversie van de voet.","Innervatie: n. fibularis profundus.","Origo: laterale tibia + membrana interossea. Insertie: os cuneiforme mediale en basis MT I.","Uitval → klapvoet / ‘steppage gait’."],"n":4},{"id":"onderste_ext_m_extensor_hallucis_longus","f":"m. extensor hallucis longus","b":["Functie: extensie van de grote teen, dorsaalflexie van de enkel.","Innervatie: n. fibularis profundus.","Origo: fibula + membrana interossea. Insertie: phalanx distalis hallux."],"n":0},{"id":"onderste_ext_m_extensor_digitorum_longus","f":"m. extensor digitorum longus","b":["Functie: extensie van tenen II–V, dorsaalflexie enkel en eversie voet.","Innervatie: n. fibularis profundus.","Origo: condylus lateralis tibiae, fibula. Insertie: dorsale aponeurose tenen II–V."],"n":0},{"id":"onderste_ext_m_fibularis_fibularis_longus_en_brevis","f":"m. fibularis (peroneus) longus en brevis","b":["Functie: eversie van de voet (onderste spronggewricht) en plantairflexie van de enkel.","Innervatie: n. fibularis superficialis.","Origo: laterale fibula. Insertie: longus – onder de voet door naar os cuneiforme mediale en MT I (steunt het voetgewelf); brevis – tuberositas MT V.","Pezen lopen achter de malleolus lateralis."],"n":1},{"id":"onderste_ext_m_gastrocnemius","f":"m. gastrocnemius","b":["Functie: plantairflexie enkel en flexie knie (twee-gewrichtsspier).","Innervatie: n. tibialis.","Origo: twee koppen op de femurcondylen. Insertie: via de achillespees op de tuber calcanei.","Vormt met de soleus de m. triceps surae. Achillespeesreflex: S1."],"n":8},{"id":"onderste_ext_m_soleus","f":"m. soleus","b":["Functie: plantairflexie van de enkel (houding/staan); niet over de knie.","Innervatie: n. tibialis.","Origo: proximale tibia en fibula (dorsaal). Insertie: via achillespees op de calcaneus.","Belangrijke ‘spierpomp’ voor de veneuze terugvloed."],"n":7},{"id":"onderste_ext_m_plantaris","f":"m. plantaris","b":["Functie: zwakke plantairflexie enkel en flexie knie.","Innervatie: n. tibialis.","Klein spierbuikje met zeer lange dunne pees langs de achillespees.","Ontbreekt bij ~10%; pees bruikbaar als transplantaat."],"n":1},{"id":"onderste_ext_m_tibialis_posterior","f":"m. tibialis posterior","b":["Functie: inversie van de voet en plantairflexie enkel; belangrijke steun voor het mediale voetgewelf.","Innervatie: n. tibialis.","Origo: membrana interossea, tibia, fibula. Insertie: tuberositas ossis navicularis (+ overige tarsalia).","Pees loopt achter de malleolus medialis (tarsale tunnel). Disfunctie → verworven platvoet."],"n":3},{"id":"onderste_ext_m_flexor_hallucis_longus","f":"m. flexor hallucis longus","b":["Functie: flexie van de grote teen, plantairflexie enkel; ‘afzetspier’ bij lopen.","Innervatie: n. tibialis.","Origo: fibula (dorsaal). Insertie: phalanx distalis hallux.","Pees loopt door de tarsale tunnel."],"n":1},{"id":"onderste_ext_m_flexor_digitorum_longus","f":"m. flexor digitorum longus","b":["Functie: flexie van tenen II–V, plantairflexie enkel.","Innervatie: n. tibialis.","Origo: tibia (dorsaal). Insertie: phalanx distalis tenen II–V.","Pees loopt door de tarsale tunnel."],"n":0},{"id":"onderste_ext_m_popliteus","f":"m. popliteus","b":["Functie: ‘ontgrendelt’ de knie vanuit volledige extensie (endorotatie tibia / exorotatie femur); zwakke kniebuiger.","Innervatie: n. tibialis.","Origo: condylus lateralis femoris. Insertie: dorsale proximale tibia.","Ligt in de bodem van de fossa poplitea."],"n":2}]},{"name":"Zenuwen","cards":[{"id":"onderste_ext_plexus_lumbalis","f":"plexus lumbalis","b":["Gevormd door de ventrale rami van L1–L4, in/achter de m. psoas major.","Belangrijkste takken: n. femoralis, n. obturatorius, n. cutaneus femoris lateralis (en n. iliohypogastricus, ilioinguinalis, genitofemoralis).","Verzorgt ventrale en mediale zijde van het bovenbeen."],"n":0},{"id":"onderste_ext_n_femoralis_l2_l4","f":"n. femoralis (L2–L4)","b":["Grootste tak van de plexus lumbalis; loopt door de lacuna musculorum lateraal van de a. femoralis.","Motorisch: alle ventrale bovenbeenspieren (m. quadriceps femoris, m. sartorius) + m. iliacus en deel m. pectineus.","Sensibel: ventrale dij en via de n. saphenus de mediale onderbeen en voet.","Uitval → geen knie-extensie, verlaagde kniepeesreflex."],"n":12},{"id":"onderste_ext_n_obturatorius_l2_l4","f":"n. obturatorius (L2–L4)","b":["Tak van de plexus lumbalis; loopt via de canalis obturatorius naar het bovenbeen.","Motorisch: alle mediale bovenbeenspieren (adductoren, m. gracilis, m. obturatorius externus).","Sensibel: klein huidgebied mediaal aan de dij.","Kan geprikkeld/beschadigd raken bij bekkenoperaties of een hernia obturatoria."],"n":12},{"id":"onderste_ext_plexus_sacralis","f":"plexus sacralis","b":["Gevormd door de ventrale rami van L4–S4 (truncus lumbosacralis L4–L5 + S1–S4), op de m. piriformis.","Belangrijkste takken: n. gluteus superior, n. gluteus inferior, n. ischiadicus, n. cutaneus femoris posterior, n. pudendus.","Verlaat het bekken via het foramen ischiadicum majus."],"n":0},{"id":"onderste_ext_n_gluteus_superior","f":"n. gluteus superior","b":["Tak van de plexus sacralis (L4–S1); verlaat het bekken via het foramen suprapiriforme.","Motorisch: m. gluteus medius, m. gluteus minimus, m. tensor fasciae latae.","Uitval → positieve Trendelenburg (waggelgang). Let op bij intramusculaire injecties: spuit in het lateraal-craniale kwadrant."],"n":2},{"id":"onderste_ext_n_gluteus_inferior","f":"n. gluteus inferior","b":["Tak van de plexus sacralis (L5–S2); verlaat het bekken via het foramen infrapiriforme.","Motorisch: m. gluteus maximus.","Uitval → moeite met opstaan uit stoel en traplopen."],"n":1},{"id":"onderste_ext_n_ischiadicus","f":"n. ischiadicus","b":["Dikste zenuw van het lichaam (L4–S3); verlaat het bekken via het foramen infrapiriforme.","Loopt dorsaal in het bovenbeen onder de m. biceps femoris; splitst meestal boven de fossa poplitea in de n. tibialis en n. fibularis communis.","Motorisch: hamstrings en deel m. adductor magnus; via eindtakken alle onderbeen- en voetspieren."],"n":5},{"id":"onderste_ext_n_tibialis","f":"n. tibialis","b":["Tak van de n. ischiadicus; loopt midden door de fossa poplitea, dan tussen de oppervlakkige en diepe kuitspieren, door de tarsale tunnel.","Motorisch: alle dorsale spieren van boven- en onderbeen (m.u.v. caput breve m. biceps femoris) + hamstringdeel m. adductor magnus + voetzoolspieren.","Sensibel: voetzool (nn. plantares) en via n. suralis de laterale voetrand.","Uitval → geen plantairflexie (niet op tenen staan)."],"n":13},{"id":"onderste_ext_n_fibularis_fibularis_communis","f":"n. fibularis (peroneus) communis","b":["Tak van de n. ischiadicus; loopt lateraal langs de fossa poplitea en om het collum fibulae.","Motorisch: caput breve m. biceps femoris; splitst in n. fibularis superficialis en profundus.","Zeer kwetsbaar bij het collum fibulae (gips, benen over elkaar, fibulakopfractuur) → klapvoet."],"n":3},{"id":"onderste_ext_n_fibularis_fibularis_superficialis","f":"n. fibularis (peroneus) superficialis","b":["Tak van de n. fibularis communis; loopt in het laterale compartiment.","Motorisch: m. fibularis longus en brevis (eversie).","Sensibel: grootste deel van de voetrug en distale laterale onderbeen."],"n":8},{"id":"onderste_ext_n_fibularis_fibularis_profundus","f":"n. fibularis (peroneus) profundus","b":["Tak van de n. fibularis communis; loopt in het voorste compartiment met de a. tibialis anterior.","Motorisch: alle ventrale onderbeenspieren (m. tibialis anterior, m. extensor hallucis longus, m. extensor digitorum longus) + korte spieren van de voetrug.","Sensibel: alleen de huid tussen de 1e en 2e teen.","Uitval → klapvoet (geen dorsaalflexie)."],"n":11},{"id":"onderste_ext_n_cutaneus_femoris_lateralis","f":"n. cutaneus femoris lateralis","b":["Sensibele tak van de plexus lumbalis (L2–L3).","Loopt vlak mediaal van de SIAS onder/door het lig. inguinale.","Verzorgt de laterale dij. Beknelling → meralgia paraesthetica (branderig gevoel lateraal bovenbeen)."],"n":1},{"id":"onderste_ext_n_cutaneus_femoris_posterior","f":"n. cutaneus femoris posterior","b":["Sensibele tak van de plexus sacralis (S1–S3); verlaat het bekken via het foramen infrapiriforme.","Verzorgt de huid van de achterzijde van het bovenbeen en de bil (onderzijde).","Loopt onder de fascia lata midden dorsaal in het bovenbeen."],"n":1},{"id":"onderste_ext_n_saphenus","f":"n. saphenus","b":["Langste sensibele tak van de n. femoralis (L3–L4).","Loopt door het kanaal van Hunter, dan mediaal aan de knie mee met de v. saphena magna.","Verzorgt de huid van de mediale onderbeen en mediale voetrand."],"n":4},{"id":"onderste_ext_n_suralis","f":"n. suralis","b":["Sensibele zenuw gevormd door samenkomst van de n. cutaneus surae medialis (uit n. tibialis) en lateralis (uit n. fibularis communis).","Loopt mee met de v. saphena parva achter de malleolus lateralis.","Verzorgt de laterale voetrand en laterale hiel. Veel gebruikt voor zenuwbiopsie."],"n":4}]},{"name":"Bloedvaten","cards":[{"id":"onderste_ext_a_iliaca_externa","f":"a. iliaca externa","b":["Tak van de a. iliaca communis (splitsing op ca. L5/S1-niveau ter hoogte van het SI-gewricht).","Loopt langs de m. psoas naar het lig. inguinale.","Wordt onder het lig. inguinale (lacuna vasorum) de a. femoralis."],"n":2},{"id":"onderste_ext_a_femoralis","f":"a. femoralis","b":["Voortzetting van de a. iliaca externa onder het lig. inguinale.","Loopt door de trigonum femorale en het kanaal van Hunter; wordt na de hiatus adductorius de a. poplitea.","Palpabel in de lies halverwege SIAS en symfyse (‘NAVeL’: lateraal→mediaal zenuw, arterie, vene). Toegang voor katheterisatie."],"n":5},{"id":"onderste_ext_a_profunda_femoris","f":"a. profunda femoris","b":["Grootste tak van de a. femoralis (ca. 4 cm onder lig. inguinale).","Belangrijkste bloedvoorziening van het bovenbeen (aa. perforantes naar de dorsale spieren).","Geeft de aa. circumflexae femoris medialis en lateralis af."],"n":1},{"id":"onderste_ext_a_circumflexa_femoris_medialis_en_lateralis","f":"a. circumflexa femoris medialis en lateralis","b":["Takken van de a. profunda femoris (soms direct van de a. femoralis).","Vormen een ring rond het collum femoris.","Medialis is de belangrijkste bloedvoorziening van de femurkop → beschadiging bij collumfractuur geeft kopnecrose."],"n":0},{"id":"onderste_ext_a_poplitea","f":"a. poplitea","b":["Voortzetting van de a. femoralis na de hiatus adductorius.","Ligt het diepst in de fossa poplitea (direct op het bot/kapsel).","Splitst onder de m. popliteus in a. tibialis anterior en posterior. Palpabel in de knieholte met gebogen knie (moeilijk)."],"n":5},{"id":"onderste_ext_a_tibialis_anterior","f":"a. tibialis anterior","b":["Tak van de a. poplitea; gaat door de membrana interossea naar het voorste compartiment.","Loopt met de n. fibularis profundus.","Wordt op de voetrug de a. dorsalis pedis."],"n":3},{"id":"onderste_ext_a_dorsalis_pedis","f":"a. dorsalis pedis","b":["Voortzetting van de a. tibialis anterior op de voetrug.","Palpabel lateraal van de pees van de m. extensor hallucis longus.","Standaardpulsatie bij vaatonderzoek (perifeer arterieel vaatlijden)."],"n":1},{"id":"onderste_ext_a_tibialis_posterior","f":"a. tibialis posterior","b":["Tak van de a. poplitea; loopt in het diep dorsale compartiment met de n. tibialis.","Gaat door de tarsale tunnel naar de voetzool (aa. plantares).","Palpabel achter de malleolus medialis."],"n":3},{"id":"onderste_ext_a_fibularis_fibularis","f":"a. fibularis (peronea)","b":["Tak van de a. tibialis posterior.","Loopt langs de fibula in het diep dorsale compartiment.","Verzorgt het laterale compartiment en de laterale enkel."],"n":0},{"id":"onderste_ext_v_iliaca_externa_diep","f":"v. iliaca externa (diep)","b":["Voortzetting van de v. femoralis boven het lig. inguinale.","Loopt mediaal van de a. iliaca externa.","Vloeit samen met de v. iliaca interna tot de v. iliaca communis."],"n":0},{"id":"onderste_ext_v_femoralis_diep","f":"v. femoralis (diep)","b":["Voortzetting van de v. poplitea; loopt mediaal van de a. femoralis in de lies.","Ontvangt de v. saphena magna (in de lies) en de v. profunda femoris.","Veel voorkomende plek van diep-veneuze trombose (DVT); toegang voor centrale lijn."],"n":0},{"id":"onderste_ext_v_saphena_magna_oppervlakkig","f":"v. saphena magna (oppervlakkig)","b":["Langste vene van het lichaam; begint vóór de malleolus medialis.","Loopt langs de mediale zijde van onder- en bovenbeen (met de n. saphenus).","Mondt via de hiatus saphenus uit in de v. femoralis. Gebruikt als bypassgraft; plek van varices."],"n":0},{"id":"onderste_ext_v_poplitea_diep","f":"v. poplitea (diep)","b":["Ontstaat uit de vv. tibiales; ligt in de fossa poplitea tussen arterie (diep) en n. tibialis (oppervlakkig).","Ontvangt de v. saphena parva.","Wordt na de hiatus adductorius de v. femoralis."],"n":0},{"id":"onderste_ext_v_saphena_parva_oppervlakkig","f":"v. saphena parva (oppervlakkig)","b":["Begint achter de malleolus lateralis.","Loopt midden over de kuit omhoog (met de n. suralis).","Mondt uit in de v. poplitea in de knieholte."],"n":0},{"id":"onderste_ext_vv_tibiales_anteriores_en_posteriores_vv_fibula","f":"vv. tibiales anteriores en posteriores, vv. fibulares (diep)","b":["Paarsgewijze begeleidende venen van de gelijknamige arteriën.","Draineren de onderbeenspieren; samen met de kuitspierpomp belangrijk voor de veneuze terugvloed.","Vormen samen de v. poplitea."],"n":0},{"id":"onderste_ext_diepe_vs_oppervlakkige_venen_been","f":"diepe vs. oppervlakkige venen (been)","b":["Diepe venen (vv. profundae) lopen onder de fascie mee met de arteriën.","Oppervlakkige venen (v. saphena magna en parva) lopen subcutaan.","Verbonden via vv. perforantes met kleppen (bloed van oppervlakkig naar diep). Klepinsufficiëntie → varices."],"n":1}]}]},{"name":"Wervelkolom en rug","groups":[{"name":"Skelet","cards":[{"id":"wervelkolom_corpus_vertebrae","f":"corpus vertebrae","b":["Wervellichaam: het dragende, cilindrische ventrale deel van de wervel.","Wordt naar caudaal groter (meer belasting).","Tussen de corpora liggen de disci intervertebrales."],"n":5},{"id":"wervelkolom_arcus_vertebrae_pediculus_en_lamina","f":"arcus vertebrae (pediculus en lamina)","b":["Wervelboog: dorsaal deel dat het foramen vertebrale omsluit.","Pediculus: verbinding tussen corpus en boog (begrenst boven/onder het foramen intervertebrale).","Lamina: plat deel van de boog tussen processus transversus en spinosus (laminectomie bij decompressie)."],"n":5},{"id":"wervelkolom_processus_spinosus","f":"processus spinosus","b":["Doornuitsteeksel: wijst naar dorsaal vanuit de samenkomst van de laminae.","Palpabel in de middellijn van de rug (C7 het duidelijkst).","Aanhechting van ligg. interspinalia/supraspinale en rugspieren."],"n":9},{"id":"wervelkolom_processus_transversus","f":"processus transversus","b":["Dwarsuitsteeksel: steekt lateraal uit op de overgang pediculus–lamina.","Thoracaal: articulatie met de ribben (tuberculum costae).","Aanhechting van rugspieren en ligamenten. Cervicaal met foramen transversarium."],"n":6},{"id":"wervelkolom_processus_articularis_superior_en_inferior","f":"processus articularis superior en inferior","b":["Gewrichtsuitsteeksels: elke wervel heeft 2 superior en 2 inferior.","Vormen met de buurwervel de facetgewrichten (artt. zygapophysiales).","Stand van de gewrichtsvlakken bepaalt de bewegingsrichting per regio."],"n":2},{"id":"wervelkolom_foramen_vertebrale_en_canalis_vertebralis","f":"foramen vertebrale en canalis vertebralis","b":["Foramen vertebrale: opening per wervel tussen corpus en arcus.","Alle foramina samen vormen de canalis vertebralis met het ruggenmerg, de cauda equina en hersenvliezen.","Vernauwing = spinale stenose."],"n":5},{"id":"wervelkolom_foramen_intervertebrale","f":"foramen intervertebrale","b":["Opening tussen twee opeenvolgende wervels (begrensd door pediculi, corpus/discus en facetgewricht).","Hier verlaat de spinale zenuw (met ganglion spinale) het wervelkanaal.","Discushernia of facetartrose kan de zenuwwortel hier comprimeren (radiculopathie)."],"n":3},{"id":"wervelkolom_curvaturen_lordose_en_kyfose","f":"curvaturen: lordose en kyfose","b":["Lordose (hol naar dorsaal): cervicaal en lumbaal.","Kyfose (bol naar dorsaal): thoracaal en sacraal (primaire krommingen, al aanwezig bij geboorte).","Cervicale en lumbale lordose ontstaan secundair (hoofd optillen, lopen). Scoliose = zijwaartse kromming."],"n":0},{"id":"wervelkolom_regionale_verschillen_cervicale_thoracale_en_lum","f":"regionale verschillen cervicale, thoracale en lumbale wervels","b":["Cervicaal: klein corpus, foramen transversarium, gespleten processus spinosus, processus uncinatus.","Thoracaal: hartvormig corpus, ribfacetten (corpus en proc. transversus), lange schuin naar caudaal wijzende proc. spinosus.","Lumbaal: groot niervormig corpus, korte stevige proc. spinosus, processus costalis; facetten sagittaal gericht (flexie/extensie)."],"n":1},{"id":"wervelkolom_atlas_c1","f":"atlas (C1)","b":["Eerste halswervel: ring zonder corpus en zonder processus spinosus.","Bestaat uit arcus anterior en posterior met massae laterales.","Draagt de schedel (art. atlanto-occipitalis) en draait om de dens van de axis."],"n":0},{"id":"wervelkolom_axis_c2_en_dens_axis","f":"axis (C2) en dens axis","b":["Tweede halswervel met de dens (tand) die omhoog steekt.","De dens vormt de draaias voor de atlas (art. atlanto-axialis mediana), op zijn plaats gehouden door het lig. transversum atlantis.","Densfractuur kan het ruggenmerg bedreigen."],"n":0},{"id":"wervelkolom_foramina_transversaria","f":"foramina transversaria","b":["Openingen in de processus transversi van de halswervels (C1–C6).","Hier loopt de a. vertebralis (meestal vanaf C6) omhoog naar de schedel.","Begeleidende venen lopen mee."],"n":1},{"id":"wervelkolom_processus_uncinatus","f":"processus uncinatus","b":["Opstaande rand aan de laterale bovenzijde van de cervicale corpora (C3–C7).","Vormt met de wervel erboven de unco-vertebrale gewrichten (gewrichten van Luschka).","Artrose hier kan het foramen intervertebrale vernauwen."],"n":3},{"id":"wervelkolom_vertebra_prominens_c7","f":"vertebra prominens (C7)","b":["Zevende halswervel met de langste, niet-gespleten processus spinosus van de halswervelkolom.","Goed zichtbaar en palpabel: oriëntatiepunt om wervels te tellen.","Aanhechting lig. nuchae."],"n":0},{"id":"wervelkolom_vertebrae_thoracales_ribaanhechtingsplaatsen","f":"vertebrae thoracales: ribaanhechtingsplaatsen","b":["12 borstwervels met ribfacetten.","Fovea costalis superior/inferior op het corpus (voor de ribkop) en fovea costalis processus transversi (voor het tuberculum costae; T1–T10).","Vormen samen de art. capitis costae en art. costotransversaria → beperken rotatie en lateroflexie minder dan flexie."],"n":0},{"id":"wervelkolom_vertebrae_lumbales_en_processus_costalis","f":"vertebrae lumbales en processus costalis","b":["5 lendenwervels: grootste corpora.","De ‘processus transversus’ heet lumbaal processus costalis (rudiment van een rib).","L4–L5 en L5–S1 zijn de meest voorkomende niveaus van discushernia."],"n":1},{"id":"wervelkolom_os_sacrum","f":"os sacrum","b":["Heiligbeen: 5 gefuseerde sacrale wervels.","Articuleert met L5 (lumbosacrale overgang, promontorium) en de ossa ilia (SI-gewrichten).","Foramina sacralia anteriora en posteriora voor de sacrale zenuwen; canalis sacralis eindigt in de hiatus sacralis."],"n":3},{"id":"wervelkolom_os_coccygis","f":"os coccygis","b":["Stuitje: 3–4 gefuseerde rudimentaire wervels.","Articuleert met de apex van het os sacrum.","Aanhechting van bekkenbodemspieren en m. gluteus maximus."],"n":0}]},{"name":"Gewrichten","cards":[{"id":"wervelkolom_articulatio_atlanto_occipitalis","f":"articulatio atlanto-occipitalis","b":["Tussen condyli occipitales en de massae laterales van de atlas.","Ellipsoïd gewricht: vooral flexie/extensie (‘ja-knikken’) en wat lateroflexie.","Geen rotatie."],"n":0},{"id":"wervelkolom_articulatio_atlanto_axialis","f":"articulatio atlanto-axialis","b":["Tussen atlas en axis: mediaal rond de dens (radgewricht) en twee laterale gewrichten.","Vooral rotatie (‘nee-schudden’): ca. 50% van de totale nekrotatie.","Dens gestabiliseerd door lig. transversum atlantis."],"n":0},{"id":"wervelkolom_facetgewrichten_artt_zygapophysiales","f":"facetgewrichten (artt. zygapophysiales)","b":["Synoviale gewrichten tussen processus articulares van opeenvolgende wervels.","Stand van de facetten bepaalt de beweging: cervicaal schuin (alle richtingen), thoracaal frontaal (rotatie), lumbaal sagittaal (flexie/extensie).","Facetartrose → lage rugpijn, vernauwing foramen intervertebrale."],"n":2},{"id":"wervelkolom_lig_flavum","f":"ligamentum flavum","b":["Gele, elastische band tussen de laminae van opeenvolgende wervels (dorsale wand wervelkanaal).","Elastine helpt terugveren uit flexie.","Wordt gepasseerd bij een lumbaalpunctie (‘plop’); verdikking draagt bij aan spinale stenose."],"n":3},{"id":"wervelkolom_lig_nuchae_ligg_interspinalia_en_supraspinale","f":"lig. nuchae, ligg. interspinalia en supraspinale","b":["Ligg. interspinalia: tussen opeenvolgende processus spinosi.","Lig. supraspinale: over de toppen van de processus spinosi (C7–sacrum).","Lig. nuchae: craniale voortzetting van het supraspinale ligament in de nek (protuberantia occipitalis externa–C7); aanhechting m. trapezius. Remmen flexie."],"n":2},{"id":"wervelkolom_symphyses_intervertebrales","f":"symphyses intervertebrales","b":["Kraakbenige verbindingen (amfiartrosen) tussen de wervellichamen via de discus intervertebralis.","Kleine beweging per segment, groot bereik over de hele kolom.","Opvangen van axiale belasting."],"n":0},{"id":"wervelkolom_discus_intervertebralis_nucleus_pulposus_en_anul","f":"discus intervertebralis (nucleus pulposus en anulus fibrosus)","b":["Tussenwervelschijf tussen de corpora (vanaf C2–C3).","Nucleus pulposus: gelatineuze kern (waterrijk), verdeelt druk.","Anulus fibrosus: concentrische vezelringen eromheen. Scheur in de anulus → nucleus puilt uit (hernia nuclei pulposi), meestal posterolateraal."],"n":8},{"id":"wervelkolom_ligg_longitudinale_anterius_en_posterius","f":"ligg. longitudinale anterius en posterius","b":["Anterius: brede band over de voorzijde van corpora en disci; remt extensie.","Posterius: smallere band aan de achterzijde van de corpora in het wervelkanaal; remt flexie.","Doordat het posterieure ligament mediaal sterk is en lateraal smal, ontstaan hernia’s vooral posterolateraal."],"n":0}]},{"name":"Spieren","cards":[{"id":"wervelkolom_m_sternocleidomastoideus","f":"m. sternocleidomastoideus","b":["Functie: eenzijdig – lateroflexie naar dezelfde kant en rotatie van het hoofd naar de andere kant; tweezijdig – flexie hals (en extensie hoofd), hulpademhaling.","Innervatie: n. accessorius (N. XI).","Origo: manubrium sterni en mediale clavicula. Insertie: processus mastoideus.","Scheidt de voorste en laterale halsdriehoek."],"n":0},{"id":"wervelkolom_m_erector_spinae","f":"m. erector spinae","b":["Autochtone (intrinsieke) rugspier met drie kolommen: m. iliocostalis (lateraal), m. longissimus, m. spinalis (mediaal).","Functie: extensie (tweezijdig) en lateroflexie (eenzijdig) van de wervelkolom; houdingsspier.","Innervatie: rami dorsales van de spinale zenuwen.","Loopt van sacrum/bekken tot schedel."],"n":7},{"id":"wervelkolom_m_splenius_cervicis_en_capitis","f":"m. splenius (cervicis en capitis)","b":["Intrinsieke rugspier in de nek (‘verbandspier’).","Functie: tweezijdig extensie van hoofd/nek; eenzijdig lateroflexie en rotatie naar dezelfde kant.","Innervatie: rami dorsales van de cervicale spinale zenuwen.","Origo: lig. nuchae, proc. spinosi C7–T6. Insertie: capitis – proc. mastoideus/os occipitale; cervicis – proc. transversi C1–C3."],"n":4},{"id":"wervelkolom_intrinsieke_vs_extrinsieke_rugspieren","f":"intrinsieke vs. extrinsieke rugspieren","b":["Intrinsiek (autochtoon): werken op de wervelkolom (m. erector spinae, m. splenius, diepe korte spieren); innervatie door rami dorsales.","Extrinsiek: liggen oppervlakkig, werken op schoudergordel/arm (m. trapezius, m. latissimus dorsi, mm. rhomboidei, m. levator scapulae); innervatie door rami ventrales/plexus brachialis (trapezius: N. XI).","Extrinsieke rugspieren zijn functioneel schoudergordelspieren."],"n":10}]},{"name":"Zenuwen","cards":[{"id":"wervelkolom_n_accessorius_n_xi_hals_en_rug","f":"n. accessorius (N. XI) – hals en rug","b":["Hersenzenuw XI.","Motorisch: m. trapezius en m. sternocleidomastoideus.","Test: schouders optrekken en hoofd draaien tegen weerstand."],"n":0},{"id":"wervelkolom_rami_dorsales_nn_spinales","f":"rami dorsales nn. spinales","b":["Dorsale takken van de spinale zenuwen, ontstaan direct na het foramen intervertebrale.","Motorisch: m. erector spinae en alle overige intrinsieke rugspieren.","Sensibel: strook huid over de rug langs de middellijn; ook de facetgewrichten."],"n":0},{"id":"wervelkolom_dermatomen","f":"dermatomen","b":["Huidgebied dat sensibel verzorgd wordt door één spinale zenuw(wortel).","Oriëntatiepunten: C6 duim, C7 middelvinger, C8 pink, T4 tepel, T10 navel, L1 lies, L4 mediale onderbeen/grote teen-zijde, L5 voetrug, S1 laterale voetrand/voetzool.","Verschil met perifere huidzenuwgebieden: dermatoom = wortel, huidzenuwgebied = perifere zenuw."],"n":2}]},{"name":"Bloedvaten","cards":[{"id":"wervelkolom_a_vertebralis","f":"a. vertebralis","b":["Eerste tak van de a. subclavia.","Loopt omhoog door de foramina transversaria C6–C1, door het foramen magnum.","Beide aa. vertebrales vormen samen de a. basilaris (achterste circulatie hersenen). Geeft ook spinale takken af."],"n":2},{"id":"wervelkolom_takken_uit_de_aorta_wervelkolom","f":"takken uit de aorta (wervelkolom)","b":["Segmentale aa. intercostales posteriores (thoracaal) en aa. lumbales (lumbaal) uit de aorta.","Geven rami spinales af naar wervels en ruggenmerg (radiculaire arteriën).","Grootste radiculaire arterie: a. van Adamkiewicz (meestal links, T9–L2) → belangrijk bij aortachirurgie."],"n":0},{"id":"wervelkolom_interne_en_externe_vertebrale_veneuze_plexus_ivv","f":"interne en externe vertebrale veneuze plexus (IVVP/EVVP)","b":["IVVP: klepvrij veneus netwerk in het epidurale vet van het wervelkanaal. EVVP: rond de buitenzijde van de wervels.","Ze zijn met elkaar en met de v. cava/v. azygos verbonden.","Klepvrij → route voor metastasering (bv. prostaatcarcinoom naar wervels) en infecties."],"n":3}]}]},{"name":"Aanhechtingen, openingen & fasciae","groups":[{"name":"Aanhechtingen","cards":[{"id":"aanhechtinge_processus_coracoideus_aanhechtingen","f":"processus coracoideus (aanhechtingen)","b":["Spieren: m. pectoralis minor, m. coracobrachialis, caput breve m. biceps brachii.","Banden: lig. coracoclaviculare, lig. coracoacromiale.","Pectoralis minor trekt de scapula naar voren/omlaag; de andere twee bewegen de arm in anteflexie/adductie."],"n":4},{"id":"aanhechtinge_epicondylus_medialis_humeri_caput_commune_flexo","f":"epicondylus medialis humeri (caput commune flexorum)","b":["Gemeenschappelijke origo van de oppervlakkige onderarmflexoren: m. pronator teres, m. flexor carpi radialis, m. palmaris longus, m. flexor carpi ulnaris, m. flexor digitorum superficialis.","Functie: palmairflexie pols en vingers, pronatie.","Overbelasting → golferselleboog (epicondylitis medialis)."],"n":0},{"id":"aanhechtinge_epicondylus_lateralis_humeri_caput_commune_exte","f":"epicondylus lateralis humeri (caput commune extensorum)","b":["Gemeenschappelijke origo van de onderarmextensoren: m. extensor carpi radialis brevis, m. extensor digitorum, m. extensor digiti minimi, m. extensor carpi ulnaris (+ m. supinator).","Functie: dorsaalflexie pols en extensie vingers.","Overbelasting → tenniselleboog (epicondylitis lateralis)."],"n":0},{"id":"aanhechtinge_tuberositas_radii_aanhechtingen","f":"tuberositas radii (aanhechtingen)","b":["Insertie van de pees van de m. biceps brachii.","Doordat de pees in pronatie om de radius gewikkeld is, werkt de biceps als sterke supinator.","Distale bicepspeesruptuur → zwakte bij supinatie en flexie."],"n":0},{"id":"aanhechtinge_tuber_ischiadicum_aanhechtingen","f":"tuber ischiadicum (aanhechtingen)","b":["Origo van de hamstrings: m. semitendinosus, m. semimembranosus, caput longum m. biceps femoris.","Ook: hamstringdeel van de m. adductor magnus, m. quadratus femoris, lig. sacrotuberale.","Functie hamstrings: extensie heup en flexie knie."],"n":3},{"id":"aanhechtinge_trochanter_minor_aanhechtingen","f":"trochanter minor (aanhechtingen)","b":["Insertie van de m. iliopsoas.","Functie: flexie van de heup (en lichte exorotatie).","Avulsie bij adolescenten na krachtige heupflexie."],"n":3},{"id":"aanhechtinge_tuberositas_tibiae_aanhechtingen","f":"tuberositas tibiae (aanhechtingen)","b":["Insertie van het lig. patellae (eindpees m. quadriceps femoris).","Functie: extensie van de knie.","Overbelasting bij groeiende kinderen → Osgood-Schlatter."],"n":4},{"id":"aanhechtinge_pes_anserinus_ganzenvoet","f":"pes anserinus (ganzenvoet)","b":["Gemeenschappelijke insertie mediaal op de proximale tibia van drie pezen: m. sartorius, m. gracilis, m. semitendinosus (ezelsbrug: ‘Say Grace before Tea’).","Elke spier komt uit een ander compartiment en een andere zenuw (n. femoralis, n. obturatorius, n. tibialis).","Functie: flexie en endorotatie knie; ondersteunt de mediale knie. Bursitis anserina geeft mediale kniepijn."],"n":0},{"id":"aanhechtinge_tendo_calcaneus_achillespees","f":"tendo calcaneus (achillespees)","b":["Gemeenschappelijke pees van de m. triceps surae (m. gastrocnemius + m. soleus) (+ m. plantaris).","Insertie: tuber calcanei.","Functie: plantairflexie enkel (afzetten). Ruptuur → test van Thompson positief. Reflex S1."],"n":0}]},{"name":"Openingen (aperturae)","cards":[{"id":"aanhechtinge_voorste_scalenuspoort","f":"voorste scalenuspoort","b":["Tussen m. sternocleidomastoideus en m. scalenus anterior.","Doorgang: v. subclavia (en n. phrenicus loopt op de m. scalenus anterior).","De vene loopt dus vóór de m. scalenus anterior, de arterie erachter."],"n":0},{"id":"aanhechtinge_achterste_scalenuspoort","f":"achterste scalenuspoort","b":["Tussen m. scalenus anterior en m. scalenus medius, boven de 1e rib.","Doorgang: a. subclavia en de trunci van de plexus brachialis.","Vernauwing (bv. halsrib) → thoracic outlet syndroom."],"n":0},{"id":"aanhechtinge_sulcus_intertubercularis_doorgang","f":"sulcus intertubercularis (doorgang)","b":["Groeve tussen tuberculum majus en minus humeri.","Bevat de pees van het caput longum m. biceps brachii (met peesschede).","Overbrugd door het lig. transversum humeri."],"n":0},{"id":"aanhechtinge_sulcus_bicipitalis_medialis","f":"sulcus bicipitalis medialis","b":["Groeve mediaal tussen m. biceps brachii en m. triceps brachii aan de bovenarm.","Bevat de neurovasculaire streng: a. brachialis, vv. brachiales, n. medianus (en proximaal n. ulnaris, v. basilica).","Hier is de a. brachialis te comprimeren."],"n":0},{"id":"aanhechtinge_fossa_cubiti","f":"fossa cubiti","b":["Driehoekige elleboogkuil: begrensd door m. brachioradialis (lateraal), m. pronator teres (mediaal) en de lijn tussen de epicondylen.","Inhoud (lateraal→mediaal): bicepspees, a. brachialis, n. medianus (‘TAN’); oppervlakkig de v. mediana cubiti.","Dak: aponeurosis bicipitalis."],"n":0},{"id":"aanhechtinge_carpale_tunnel_canalis_carpalis","f":"carpale tunnel (canalis carpalis)","b":["Kanaal tussen de ossa carpalia (bodem) en het retinaculum flexorum (dak).","Inhoud: n. medianus + 9 pezen: 4× m. flexor digitorum superficialis, 4× m. flexor digitorum profundus, 1× m. flexor pollicis longus.","Druk op de n. medianus → carpaletunnelsyndroom (tintelingen duim–ringvinger, thenaratrofie)."],"n":0},{"id":"aanhechtinge_canalis_ulnaris_kanaal_van_guyon","f":"canalis ulnaris (kanaal van Guyon)","b":["Kanaal aan de ulnaire palmaire zijde van de pols tussen os pisiforme en hamulus ossis hamati, boven het retinaculum flexorum.","Inhoud: n. ulnaris en a. ulnaris.","Compressie (fietsers) → uitval van ulnaris-handspieren met behoud van de onderarmspieren."],"n":1},{"id":"aanhechtinge_tabatiere_anatomique_anatomische_snuifdoos","f":"tabatière anatomique (anatomische snuifdoos)","b":["Kuiltje aan de dorsoradiale pols bij gestrekte duim.","Begrenzing: palmair m. abductor pollicis longus en m. extensor pollicis brevis; dorsaal m. extensor pollicis longus.","Bodem: os scaphoideum (en trapezium); inhoud: a. radialis. Drukpijn → verdenking scaphoidfractuur."],"n":1},{"id":"aanhechtinge_foramen_suprapiriforme","f":"foramen suprapiriforme","b":["Deel van het foramen ischiadicum majus boven de m. piriformis.","Doorgang: n. gluteus superior en a./v. glutea superior.","Ligt in het bovenste deel van de bilregio."],"n":1},{"id":"aanhechtinge_foramen_infrapiriforme","f":"foramen infrapiriforme","b":["Deel van het foramen ischiadicum majus onder de m. piriformis.","Doorgang: n. ischiadicus, n. gluteus inferior, n. cutaneus femoris posterior, n. pudendus en a./v. glutea inferior en pudenda interna.","Piriformissyndroom: compressie van de n. ischiadicus."],"n":2},{"id":"aanhechtinge_lacuna_vasorum","f":"lacuna vasorum","b":["Mediale doorgang onder het lig. inguinale, gescheiden van de lacuna musculorum door de arcus iliopectineus.","Inhoud (lateraal→mediaal): a. femoralis, v. femoralis, lymfevaten (canalis femoralis, ‘lege ruimte’).","Via de canalis femoralis kan een hernia femoralis ontstaan."],"n":0},{"id":"aanhechtinge_lacuna_musculorum","f":"lacuna musculorum","b":["Laterale doorgang onder het lig. inguinale.","Inhoud: m. iliopsoas en n. femoralis (+ n. cutaneus femoris lateralis).","Gescheiden van de lacuna vasorum door de arcus iliopectineus."],"n":0},{"id":"aanhechtinge_canalis_obturatorius","f":"canalis obturatorius","b":["Kanaal in de bovenrand van het foramen obturatum (niet afgedekt door de membrana obturatoria).","Doorgang: n. obturatorius, a. en v. obturatoria.","Verbinding tussen bekken en mediaal compartiment van het bovenbeen."],"n":0},{"id":"aanhechtinge_canalis_adductorius_kanaal_van_hunter","f":"canalis adductorius (kanaal van Hunter)","b":["Kanaal in het middelste derde van het bovenbeen onder de m. sartorius, tussen m. vastus medialis en de adductoren.","Inhoud: a. femoralis, v. femoralis, n. saphenus (en tak naar m. vastus medialis).","Eindigt in de hiatus adductorius."],"n":1},{"id":"aanhechtinge_hiatus_adductorius","f":"hiatus adductorius","b":["Opening in de insertie van de m. adductor magnus, net boven de knie.","Doorgang: a. en v. femoralis van ventraal naar dorsaal.","Na de hiatus heten ze a. en v. poplitea."],"n":0},{"id":"aanhechtinge_fossa_poplitea","f":"fossa poplitea","b":["Ruitvormige knieholte: boven m. biceps femoris (lateraal) en m. semimembranosus/semitendinosus (mediaal), onder de twee gastrocnemiuskoppen.","Inhoud (oppervlakkig→diep): n. tibialis, v. poplitea, a. poplitea; lateraal de n. fibularis communis.","Bakercyste ontstaat hier."],"n":0},{"id":"aanhechtinge_tarsale_tunnel","f":"tarsale tunnel","b":["Kanaal achter en onder de malleolus medialis onder het retinaculum flexorum.","Inhoud (ventraal→dorsaal): pees m. tibialis posterior, pees m. flexor digitorum longus, a./v. tibialis posterior, n. tibialis, pees m. flexor hallucis longus (‘Tom, Dick And Nervous Harry’).","Compressie n. tibialis → tarsaletunnelsyndroom."],"n":1},{"id":"aanhechtinge_foramen_transversarium","f":"foramen transversarium","b":["Opening in de processus transversus van de halswervels.","Doorgang: a. vertebralis (C6–C1) en vv. vertebrales.","C7 heeft wel een foramen, maar daar loopt de arterie meestal niet doorheen."],"n":5},{"id":"aanhechtinge_foramen_vertebrale_foramen_intervertebrale_en_c","f":"foramen vertebrale, foramen intervertebrale en canalis vertebralis (inhoud)","b":["Canalis vertebralis (= alle foramina vertebralia): ruggenmerg (tot ca. L1–L2), cauda equina, meninges, liquor, epiduraal vet en de IVVP.","Foramen intervertebrale: spinale zenuw met ganglion spinale + rami spinales van arteriën/venen.","Compressie in het foramen intervertebrale → radiculaire pijn in het dermatoom."],"n":6}]},{"name":"Fasciae & compartimenten","cards":[{"id":"aanhechtinge_fascia_brachii_antebrachii_en_palmaris","f":"fascia brachii, antebrachii en palmaris","b":["Fascia brachii: omhult de bovenarmspieren; septa intermuscularia scheiden flexor- en extensorcompartiment.","Fascia antebrachii: omhult de onderarm; verdikt bij de pols tot retinacula.","Aponeurosis/fascia palmaris: stevige driehoekige plaat in de handpalm (m. palmaris longus); verkorting = ziekte van Dupuytren."],"n":0},{"id":"aanhechtinge_retinaculum_flexorum_en_extensorum_pols","f":"retinaculum flexorum en extensorum (pols)","b":["Retinaculum flexorum (lig. carpi transversum): dak van de carpale tunnel tussen de carpale uitsteeksels.","Retinaculum extensorum: dorsaal over de pols; verdeelt de extensorpezen in 6 peesvakken.","Houden de pezen op hun plaats (voorkomen ‘bowstringing’)."],"n":0},{"id":"aanhechtinge_fascia_lata_fascia_cruris_en_fascia_plantaris","f":"fascia lata, fascia cruris en fascia plantaris","b":["Fascia lata: stevige fascie om het bovenbeen; lateraal verdikt tot de tractus iliotibialis.","Fascia cruris: omhult het onderbeen; septa vormen de compartimenten.","Fascia (aponeurosis) plantaris: van calcaneus naar de tenen; ondersteunt het longitudinale voetgewelf (fasciitis plantaris → hielpijn)."],"n":0},{"id":"aanhechtinge_lig_inguinale_tractus_iliotibialis_en_retinacul","f":"ligamentum inguinale, tractus iliotibialis en retinacula (been)","b":["Lig. inguinale: onderrand aponeurose m. obliquus externus, van SIAS naar tuberculum pubicum; dak van lacuna vasorum/musculorum.","Tractus iliotibialis: verdikte strook van de fascia lata van crista iliaca naar tuberculum van Gerdy (tibia); insertie m. tensor fasciae latae en m. gluteus maximus.","Retinacula bij de enkel (extensorum, flexorum, fibularium) houden de pezen op hun plaats."],"n":0},{"id":"aanhechtinge_compartimenten_bovenarm_en_onderarm","f":"compartimenten bovenarm en onderarm","b":["Bovenarm: ventraal (flexoren, n. musculocutaneus) en dorsaal (extensoren, n. radialis).","Onderarm: ventraal (flexoren/pronatoren, n. medianus en n. ulnaris) en dorsaal (extensoren/supinator, n. radialis), gescheiden door radius, ulna en membrana interossea.","Compartimentsyndroom: drukverhoging in een gesloten compartiment → spierischemie."],"n":0},{"id":"aanhechtinge_compartimenten_bovenbeen_en_onderbeen","f":"compartimenten bovenbeen en onderbeen","b":["Bovenbeen: ventraal (knie-extensoren, n. femoralis), mediaal (adductoren, n. obturatorius), dorsaal (hamstrings, n. ischiadicus).","Onderbeen: ventraal (dorsaalflexoren, n. fibularis profundus), lateraal (evertoren, n. fibularis superficialis), oppervlakkig en diep dorsaal (plantairflexoren, n. tibialis).","Compartimentsyndroom komt het meest voor in het voorste compartiment van het onderbeen (na tibiafractuur)."],"n":0}]}]}]};
